89	/* ── stdout mutex — shared with nsh_commands.c ──────────────── */
90	/* Prevents concurrent printf from outbound_dispatch_task and cli_thread
91	 * which causes adbd shell_service_uv assert (wait_ack != 0). */
92	pthread_mutex_t g_stdout_lock = PTHREAD_MUTEX_INITIALIZER;
