144	/**
145	 * Runs in a background thread: waits for network, then starts all
146	 * network-dependent services. Main thread is NOT blocked.
147	 */
148	static void* network_watch_task(void* arg)
149	{
150	    (void)arg;
151	    syslog(LOG_INFO, "[%s] Network watcher started\n", TAG);
152	
153	    network_wifi_reconnect();
154	
155	    /* PPP is brought up by the host after this process starts, and on a
156	     * cold boot it can easily take longer than the old single 30-second
157	     * attempt. Giving up once left agent/WS/REST down for the rest of the
158	     * boot even though the link came up moments later. Keep waiting. */
159	    while (!g_shutdown_requested) {
160	        if (network_wait_connected(10000) == OK) {
161	            break;
162	        }
163	        syslog(LOG_WARNING, "[%s] Network not ready yet; retrying\n", TAG);
164	        sleep(2);
165	    }
166	
167	    if (g_shutdown_requested) {
168	        return NULL;
169	    }
170	
171	    syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, network_get_ip());
172	
173	#if AGENT_SKILL_SYNC_ENABLED
174	    /* Sync skills from Bitable before starting agent loop */
175	    if (skill_sync_from_bitable() != OK) {
176	        syslog(LOG_WARNING, "[%s] Bitable skill sync failed, using local skills\n", TAG);
177	    }
178	#endif
179	
180	#ifdef CONFIG_AI_AGENT_FEISHU
181	    if (feishu_bot_start() != OK)
182	        syslog(LOG_WARNING, "[%s] feishu_bot_start failed\n", TAG);
183	#endif
184	    if (agent_loop_start() != OK)
185	        syslog(LOG_WARNING, "[%s] agent_loop_start failed\n", TAG);
186	    if (ws_server_start() != OK)
187	        syslog(LOG_WARNING, "[%s] ws_server_start failed\n", TAG);
188	#ifdef CONFIG_AI_AGENT_NODE
189	    if (node_client_start() != OK)
190	        syslog(LOG_WARNING, "[%s] node_client_start failed\n", TAG);
191	#endif
192	#ifdef CONFIG_AI_AGENT_MQTT
193	    if (mqtt_channel_start() != OK)
194	        syslog(LOG_WARNING, "[%s] mqtt_channel_start failed\n", TAG);
195	#endif
196	#ifdef CONFIG_AI_AGENT_WEIXIN
197	    if (weixin_channel_start() != OK)
198	        syslog(LOG_WARNING, "[%s] weixin_channel_start failed\n", TAG);
199	#endif
200	
201	    syslog(LOG_INFO, "[%s] All network services started!\n", TAG);
202	
203	#ifdef CONFIG_AI_AGENT_NET_RPMSG
204	    g_net_services_started = true;
205	#endif
206	
207	#ifdef CONFIG_AI_AGENT_NET_RPMSG
208	    /* Register listener for network state changes — auto-restart services on reconnect */
209	    network_register_listener(net_state_change_cb, NULL);
210	
211	    /* Keep thread alive to handle reconnection events */
212	    while (!g_shutdown_requested) {
213	        sleep(1);
214	    }
215	#endif
216	
217	    return NULL;
218	}
