220	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
221	/* -- Quickapp mqueue IPC (cross-process bridge) --------------- */
222	
223	#include <mqueue.h>
224	#include <fcntl.h>
225	#include <errno.h>
226	
227	#define VELACLAW_MQ_QAPP_IN   "/velaclaw_qapp_in"
228	#define VELACLAW_MQ_QAPP_OUT  "/velaclaw_qapp_out"
229	#define VELACLAW_MQ_MSG_SIZE  4096
230	#define VELACLAW_MQ_MAX_MSGS  4
231	
232	/**
233	 * Reads requests from the quickapp process via POSIX mqueue and feeds
234	 * them into the local message_bus inbound queue.
235	 */
236	static void *quickapp_mq_listener_task(void *arg)
237	{
238	    (void)arg;
239	    syslog(LOG_INFO, "[%s] Quickapp mqueue listener started\n", TAG);
240	
241	    struct mq_attr attr = {
242	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
243	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
244	    };
245	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_IN, O_RDONLY | O_CREAT, 0666, &attr);
246	    if (mq == (mqd_t)-1) {
247	        syslog(LOG_ERR, "[%s] Failed to open quickapp inbound mqueue: %d\n", TAG, errno);
248	        return NULL;
249	    }
250	
251	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
252	    if (!buf) {
253	        syslog(LOG_ERR, "[%s] Failed to allocate mqueue recv buffer\n", TAG);
254	        mq_close(mq);
255	        return NULL;
256	    }
257	
258	    while (1) {
259	        ssize_t n = mq_receive(mq, buf, VELACLAW_MQ_MSG_SIZE, NULL);
260	        if (n < 0) {
261	            if (errno == EINTR) continue;
262	            syslog(LOG_ERR, "[%s] mq_receive failed: %d\n", TAG, errno);
263	            break;
264	        }
265	        if (n >= (ssize_t)VELACLAW_MQ_MSG_SIZE) {
266	            n = VELACLAW_MQ_MSG_SIZE - 1;
267	        }
268	        buf[n] = '\0';
269	
270	        /* Message format: "chat_id\nquery" */
271	        char *sep = strchr(buf, '\n');
272	        if (!sep) {
273	            syslog(LOG_WARNING, "[%s] Malformed quickapp message\n", TAG);
274	            continue;
275	        }
276	        *sep = '\0';
277	        const char *chat_id = buf;
278	        const char *query = sep + 1;
279	
280	        syslog(LOG_INFO, "[%s] Quickapp request: chat_id=%s query=%.40s\n",
281	               TAG, chat_id, query);
282	
283	        agent_msg_t msg = {0};
284	        strncpy(msg.channel, AGENT_CHAN_QUICKAPP, sizeof(msg.channel) - 1);
285	        strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
286	        msg.content = strdup(query);
287	        if (msg.content) {
288	            message_bus_push_inbound(&msg);
289	        }
290	    }
291	
292	    free(buf);
293	    mq_close(mq);
294	    return NULL;
295	}
296	
297	/**
298	 * Send a reply to the quickapp process via the outbound mqueue.
299	 * Called from the outbound dispatch thread in the agent process.
300	 */
301	static void quickapp_mq_dispatch(const char *chat_id, const char *content)
302	{
303	    struct mq_attr attr = {
304	        .mq_maxmsg  = VELACLAW_MQ_MAX_MSGS,
305	        .mq_msgsize = VELACLAW_MQ_MSG_SIZE,
306	    };
307	    mqd_t mq = mq_open(VELACLAW_MQ_QAPP_OUT, O_WRONLY | O_CREAT, 0666, &attr);
308	    if (mq == (mqd_t)-1) {
309	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_open failed: %d\n", TAG, errno);
310	        return;
311	    }
312	
313	    char *buf = (char *)malloc(VELACLAW_MQ_MSG_SIZE);
314	    if (!buf) {
315	        mq_close(mq);
316	        return;
317	    }
318	    int len = snprintf(buf, VELACLAW_MQ_MSG_SIZE, "%s\n%s", chat_id, content);
319	    if (len >= (int)VELACLAW_MQ_MSG_SIZE) {
320	        len = VELACLAW_MQ_MSG_SIZE - 1;
321	        buf[len] = '\0';
322	    }
323	
324	    if (mq_send(mq, buf, len + 1, 0) != 0) {
325	        syslog(LOG_ERR, "[%s] quickapp dispatch: mq_send failed: %d\n", TAG, errno);
326	    } else {
327	        syslog(LOG_INFO, "[%s] quickapp dispatch: reply sent chat_id=%s\n", TAG, chat_id);
328	    }
329	    free(buf);
330	    mq_close(mq);
331	}
332	#endif /* CONFIG_FEATURE_SYSTEM_VELACLAW */
