334	/* ── Outbound dispatch ────────────────────────────────────────── */
335	
336	/* ── Voice failure cooldown — prevent error-message cascade ──── */
337	
338	static volatile bool s_voice_cooldown;
339	static time_t s_voice_cooldown_until;
340	
341	/**
342	 * Reads messages from the outbound queue and dispatches them to the
343	 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
344	 */
345	static void* outbound_dispatch_task(void* arg)
346	{
347	    (void)arg;
348	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
349	
350	    while (!g_shutdown_requested) {
351	        agent_msg_t msg;
352	        /* Wait indefinitely rather than polling once a second. There is
353	         * nothing to do on a timeout -- the loop just goes round -- and the
354	         * timeout costs a full timed release-and-reacquire of the queue's
355	         * mutex every second for the life of the device, which is a lot of
356	         * traffic through the scheduler's mutex bookkeeping for no gain.
357	         * Shutdown wakes this with a broadcast, so it cannot get stuck. */
358	        if (message_bus_pop_outbound(&msg, UINT32_MAX) != OK)
359	            continue;
360	        msg.channel[sizeof(msg.channel) - 1] = '\0';
361	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
362	
363	        if (!msg.content) {
364	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
365	            continue;
366	        }
367	
368	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
369	
370	        /* Mirror to the watch screen, whatever channel this is bound for.
371	         *
372	         * A reply is only routed to the channel it came from, so an exchange
373	         * over voice or WebSocket is invisible on the device even though the
374	         * device is what did the work. Mirroring at this one point covers
375	         * every channel at once -- including cron wake-ups and proactive
376	         * pushes -- instead of adding a special case to each path that
377	         * happens to remember. Skipped when the screen is already the
378	         * destination, which would otherwise double up. */
379	#ifdef CONFIG_AI_AGENT_LVGL_UI
380	        if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) != 0) {
381	            lvgl_ui_channel_post(msg.content);
382	        }
383	#endif
384	
385	        /* Let registered taps intercept before normal dispatch */
386	        if (mbus_tap_try_deliver(&msg)) {
387	            free(msg.content);
388	            continue;
389	        }
390	
391	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
392	            bool delivered = false;
393	#ifdef CONFIG_AI_AGENT_FEISHU
394	            const char* app_id = feishu_get_app_id();
395	            if (app_id && app_id[0] != '\0') {
396	                feishu_send_message(msg.chat_id, msg.content);
397	                delivered = true;
398	            }
399	#endif
400	#ifdef CONFIG_AI_AGENT_NODE
401	            if (!delivered) {
402	                delivered = node_client_send_chat_message(
403	                    msg.channel, msg.chat_id, msg.content) == OK;
404	            }
405	#endif
406	            if (!delivered) {
407	                syslog(LOG_WARNING,
408	                    "[%s] Feishu message dropped: no local config "
409	                    "and no gateway\n",
410	                    TAG);
411	            }
412	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
413	            if (msg.status)
414	                ws_server_send_status(msg.chat_id, msg.content);
415	            else
416	                ws_server_send(msg.chat_id, msg.content);
417	#ifdef CONFIG_AI_AGENT_MQTT
418	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
419	            mqtt_channel_send(msg.chat_id, msg.content);
420	#endif
421	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
422	            /* Check voice cooldown — skip voice dispatch if a recent
423	             * speak call failed, to prevent error-message cascade. */
424	            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
425	                syslog(LOG_WARNING,
426	                    "[%s] voice cooldown active, dropping message\n", TAG);
427	            } else {
428	                s_voice_cooldown = false;
429	                int vret = voice_channel_speak(msg.content);
430	                if (vret != 0) {
431	                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
432	                    s_voice_cooldown = true;
433	                    s_voice_cooldown_until = time(NULL) + 5;
434	                }
435	            }
436	#ifdef CONFIG_AI_AGENT_LVGL_UI
437	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
438	            int uret = lvgl_ui_channel_send(msg.content);
439	            if (uret != 0) {
440	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
441	            }
442	#endif
443	#ifdef CONFIG_AI_AGENT_WEIXIN
444	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
445	            /* chat_id format: "from_user_id|context_token" */
446	            char uid[64] = "";
447	            const char* ctx = "";
448	            char* sep = strchr(msg.chat_id, '|');
449	            if (sep) {
450	                size_t ulen = (size_t)(sep - msg.chat_id);
451	                if (ulen >= sizeof(uid))
452	                    ulen = sizeof(uid) - 1;
453	                memcpy(uid, msg.chat_id, ulen);
454	                uid[ulen] = '\0';
455	                ctx = sep + 1;
456	            } else {
457	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
458	            }
459	            weixin_channel_send(uid, ctx, msg.content);
460	#endif
461	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
462	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
463	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
464	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
465	            quickapp_mq_dispatch(msg.chat_id, msg.content);
466	#endif
467	        } else if (strcmp(msg.channel, "cli") == 0) {
468	            pthread_mutex_lock(&g_stdout_lock);
469	            printf("\n[Agent]: %s\nvela> ", msg.content);
470	            fflush(stdout);
471	            pthread_mutex_unlock(&g_stdout_lock);
472	            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
473	        } else {
474	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
475	        }
476	
477	        free(msg.content);
478	    }
479	
480	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
481	    return NULL;
482	}
