486	/* ── Startup timing helpers ───────────────────────────────────── */
487	
488	static inline long boot_ms(struct timespec* t0)
489	{
490	    struct timespec now;
491	    clock_gettime(CLOCK_MONOTONIC, &now);
492	    return (long)((now.tv_sec - t0->tv_sec) * 1000L + (now.tv_nsec - t0->tv_nsec) / 1000000L);
493	}
494	
495	#define BOOT_LOG(t0, phase, msg) \
496	    syslog(LOG_INFO, "[%s] [boot +%ldms] " phase ": " msg "\n", TAG, boot_ms(t0))
497	
498	#define BOOT_LOG_RC(t0, phase, msg, rc) \
499	    syslog((rc) == OK ? LOG_INFO : LOG_WARNING, \
500	        "[%s] [boot +%ldms] " phase ": " msg " (rc=%d)\n", TAG, boot_ms(t0), (rc))
501	
502	int ai_agent_main(int argc, char* argv[])
503	{
504	    (void)argc;
505	    (void)argv;
506	
507	    g_shutdown_requested = false;
508	
509	    struct timespec t0;
510	    clock_gettime(CLOCK_MONOTONIC, &t0);
511	
512	    syslog(LOG_INFO, "[%s] AI Agent - Vela AI Agent starting (build: %s)\n",
513	        TAG, AGENT_BUILD_VERSION);
514	
515	    /* ── Phase 0: Timezone ──────────────────────────────────── */
516	    /* Set TZ before any time calls so localtime_r returns CST+8.
517	     * NuttX with CONFIG_LIBC_LOCALTIME+CONFIG_LIBC_ZONEINFO supports
518	     * both POSIX ("CST-8") and zoneinfo ("Asia/Shanghai") formats. */
519	    setenv("TZ", AGENT_TIMEZONE, 1);
520	#ifdef CONFIG_LIBC_LOCALTIME
521	    tzset();
522	#endif
523	    BOOT_LOG(&t0, "P0", "timezone set");
524	
525	    /* ── Phase 0: Storage Bootstrapping (Auto-mount & Mkdir) ── */
526	
527	    struct stat st;
528	    if (stat("/data", &st) != 0) {
529	        syslog(LOG_INFO, "[%s] Mounting /data as tmpfs for simulation...\n", TAG);
530	        mount(NULL, "/data", "tmpfs", 0, NULL);
531	    }
532	
533	    /* Ensure directory structure exists (No more manual mkdir needed!) */
534	    mkdir("/data/agent", 0755);
535	    mkdir("/data/agent/config", 0755);
536	    mkdir("/data/agent/memory", 0755);
537	    mkdir("/data/agent/sessions", 0755);
538	    mkdir("/data/agent/skills", 0755);
539	    BOOT_LOG(&t0, "P0", "storage ready");
540	
541	    /* Memory info */
542	    {
543	        struct mallinfo mi = mallinfo();
544	        syslog(LOG_INFO, "[%s] [boot +%ldms] heap: arena=%d free=%d used=%d\n",
545	            TAG, boot_ms(&t0), mi.arena, mi.fordblks, mi.uordblks);
546	    }
547	
548	    /* ── Phase 1: Core infrastructure ──────────────────────── */
549	    {
550	        int rc;
551	        rc = config_store_init();
552	        BOOT_LOG_RC(&t0, "P1", "config_store_init", rc);
553	
554	        rc = message_bus_init();
555	        BOOT_LOG_RC(&t0, "P1", "message_bus_init", rc);
556	        if (rc != OK)
557	            return -1;
558	
559	        rc = memory_store_init();
560	        BOOT_LOG_RC(&t0, "P1", "memory_store_init", rc);
561	
562	        rc = session_mgr_init();
563	        BOOT_LOG_RC(&t0, "P1", "session_mgr_init", rc);
564	    }
