572	    /* ── Phase 3: Application services ─────────────────────── */
573	    {
574	        int rc;
575	#ifdef CONFIG_AI_AGENT_FEISHU
576	        rc = feishu_bot_init();
577	        BOOT_LOG_RC(&t0, "P3", "feishu_bot_init", rc);
578	#endif
579	
580	        rc = llm_proxy_init();
581	        BOOT_LOG_RC(&t0, "P3", "llm_proxy_init", rc);
582	
583	        rc = llm_router_init();
584	        BOOT_LOG_RC(&t0, "P3", "llm_router_init", rc);
585	
586	        /* node_manager must init BEFORE tool_registry so it can
587	         * register itself as a tool provider. */
588	#ifdef CONFIG_AI_AGENT_NODE
589	        rc = node_manager_init();
590	        BOOT_LOG_RC(&t0, "P3", "node_manager_init", rc);
591	#endif
592	
593	        rc = tool_registry_init();
594	        BOOT_LOG_RC(&t0, "P3", "tool_registry_init", rc);
595	
596	        rc = tool_guard_init();
597	        BOOT_LOG_RC(&t0, "P3", "tool_guard_init", rc);
598	
599	        /* Skills must init AFTER tool_registry so executable skills
600	         * can register themselves as tools. */
601	        rc = skill_loader_init();
602	        BOOT_LOG_RC(&t0, "P3", "skill_loader_init", rc);
603	
604	        rc = agent_loop_init();
605	        BOOT_LOG_RC(&t0, "P3", "agent_loop_init", rc);
606	
607	        rc = cron_service_init();
608	        BOOT_LOG_RC(&t0, "P3", "cron_service_init", rc);
609	
610	        rc = heartbeat_init();
611	        BOOT_LOG_RC(&t0, "P3", "heartbeat_init", rc);
612	
613	#ifdef CONFIG_AI_AGENT_NODE
614	        rc = node_client_init();
615	        BOOT_LOG_RC(&t0, "P3", "node_client_init", rc);
616	#endif
617	
618	#ifdef CONFIG_AI_AGENT_MQTT
619	        rc = mqtt_channel_init();
620	        BOOT_LOG_RC(&t0, "P3", "mqtt_channel_init", rc);
621	#endif
622	
623	        rc = voice_channel_init();
624	        BOOT_LOG_RC(&t0, "P3", "voice_channel_init", rc);
