685	            void* user_data);
686	        bt_instance_t* bt_ins = bluetooth_get_instance();
687	        if (bt_ins) {
688	            bt_adapter_state_t state = bt_adapter_get_state(bt_ins);
689	            if (state < BT_ADAPTER_STATE_BLE_ON) {
