702	        int attempts = 0;
703	        while (rc < 0 && attempts < 5) {
704	            rc = ble_gatt_init(&ble_cfg);
705	            if (rc < 0) {
706	                syslog(LOG_WARNING, "[%s] ble_gatt_init attempt %d failed: %d\n",
707	                    TAG, attempts + 1, rc);
708	                sleep(3);
709	            }
710	            attempts++;
711	        }
712	        if (rc == 0) {
713	            BOOT_LOG(&t0, "P5", "ble_gatt init OK");
714	        } else {
715	            BOOT_LOG(&t0, "P5", "ble_gatt FAILED after retries");
716	        }
717	    }
