719	
720	    /* Network watcher thread: reconnect + wait + start net services */
721	    if (agent_task_create(network_watch_task, "net_watch",
722	            AGENT_OUTBOUND_STACK, NULL,
723	            AGENT_OUTBOUND_PRIO)
724	        != OK) {
725	        syslog(LOG_WARNING, "[%s] Failed to start network_watch thread\n", TAG);
726	    }
727	    BOOT_LOG(&t0, "P5", "network_watch thread started (async)");
728	
729	    /* ── Phase 6: CLI thread — all services now in known state ── */
730	    {
731	        int rc = nsh_commands_start();
732	        BOOT_LOG_RC(&t0, "P6", "nsh_commands_start", rc);
733	    }
734	
735	    syslog(LOG_INFO, "[%s] [boot +%ldms] AI Agent ready. Type 'help' in NSH for commands.\n",
736	        TAG, boot_ms(&t0));
737	
738	    /* Block main thread until shutdown is requested */
739	    while (!g_shutdown_requested) {
740	        sleep(1);
741	    }
742	
743	    syslog(LOG_INFO, "[%s] Shutdown requested — stopping services...\n", TAG);
744	
745	    /* Wake all threads blocked on message bus before stopping services */
746	    message_bus_wakeup();
747	
748	    /* ── Graceful teardown (reverse of startup order) ──────── */
749	
750	    /* Phase 5 services (network-dependent) */
751	#ifdef CONFIG_AI_AGENT_WEIXIN
752	    weixin_channel_stop();
753	#endif
754	#ifdef CONFIG_AI_AGENT_NODE
755	    node_client_stop();
756	#endif
757	#ifdef CONFIG_AI_AGENT_MQTT
758	    mqtt_channel_stop();
759	#endif
760	    ws_server_stop();
761	    /* feishu_bot and agent_loop have no _stop(); they will exit
762	     * naturally once their blocking I/O returns an error after
763	     * the network sockets are closed below, or they can check
764	     * agent_shutdown_requested() in their loops. */
765	
766	#ifdef CONFIG_AI_AGENT_LVGL_UI
767	    lvgl_ui_channel_stop();
768	#endif
769	
770	    /* Phase 5 services (non-network) */
771	    cron_service_stop();
772	    heartbeat_stop();
773	
774	    /* Give threads a moment to notice and exit */
775	    usleep(500 * 1000);
776	
777	    /* Cleanup — reverse order of init */
778	    tool_media_cleanup();
779	#ifdef CONFIG_AI_AGENT_MCP
780	    mcp_bridge_cleanup();
781	#endif
782	    tool_guard_cleanup();
783	    tool_registry_cleanup();
784	    llm_cache_cleanup();
785	    vela_tls_pool_cleanup();
786	    message_bus_destroy();
787	
788	    syslog(LOG_INFO, "[%s] Shutdown complete.\n", TAG);
789	
790	    return 0;
791	}
