170	/* ── Streaming tool output ─────────────────────────────────── */
171	
172	/**
173	 * Growable buffer for streaming tool output. Starts small and
174	 * grows on demand, avoiding large upfront allocations for tools
175	 * that return small results.
176	 */
177	typedef struct {
178	    char* data;
179	    size_t len;
180	    size_t cap;
181	    size_t max_cap;
182	} agent_stream_buf_t;
183	
184	#define AGENT_STREAM_INIT_SIZE 1024
185	#define AGENT_STREAM_MAX_SIZE (32 * 1024)
186	
187	static inline int agent_stream_init(agent_stream_buf_t* sb, size_t max_cap)
188	{
189	    size_t init = AGENT_STREAM_INIT_SIZE;
190	    if (init > max_cap)
191	        init = max_cap;
192	
193	    sb->data = malloc(init);
194	    if (!sb->data)
195	        return ERROR;
196	    sb->data[0] = '\0';
197	    sb->len = 0;
198	    sb->cap = init;
199	    sb->max_cap = max_cap;
200	    return OK;
201	}
202	
203	/**
204	 * Append data to the stream buffer, growing as needed.
205	 * Returns OK on success, ERROR if max_cap would be exceeded.
206	 */
207	static inline int agent_stream_append(agent_stream_buf_t* sb,
208	    const char* chunk, size_t chunk_len)
209	{
210	    if (sb->len + chunk_len + 1 > sb->cap) {
211	        size_t new_cap = sb->cap * 2;
212	        if (new_cap < sb->len + chunk_len + 1)
213	            new_cap = sb->len + chunk_len + 1;
214	        if (new_cap > sb->max_cap)
215	            new_cap = sb->max_cap;
216	        if (sb->len + chunk_len + 1 > new_cap)
217	            return ERROR; /* would exceed max */
218	
219	        char* new_data = realloc(sb->data, new_cap);
220	        if (!new_data)
221	            return ERROR;
222	        sb->data = new_data;
223	        sb->cap = new_cap;
224	    }
225	    memcpy(sb->data + sb->len, chunk, chunk_len);
226	    sb->len += chunk_len;
227	    sb->data[sb->len] = '\0';
228	    return OK;
229	}
230	
231	/**
232	 * Detach the buffer data (caller takes ownership). Resets the stream.
233	 */
234	static inline char* agent_stream_detach(agent_stream_buf_t* sb)
235	{
236	    char* p = sb->data;
237	    sb->data = NULL;
238	    sb->len = 0;
239	    sb->cap = 0;
240	    return p;
241	}
242	
243	static inline void agent_stream_free(agent_stream_buf_t* sb)
244	{
245	    free(sb->data);
246	    sb->data = NULL;
247	    sb->len = 0;
248	    sb->cap = 0;
249	}
250	
251	/**
252	 * Execute a tool with streaming output. Uses a growable buffer
253	 * internally, then copies the result to the caller's fixed buffer.
254	 * This avoids allocating a large fixed buffer upfront for tools
255	 * that may return small results.
256	 *
257	 * Returns the number of bytes written (excluding NUL), or -1 on error.
258	 *
259	 * NOTE: tool is executed exactly ONCE. No retry to avoid double
260	 * side-effects on write/mutating tools.
261	 */
262	static inline int agent_tool_exec_streamed(
263	    const char* name, const char* input_json,
264	    char* output, size_t output_size)
265	{
266	    /* Allocate a buffer sized to output_size so the tool can write its
267	     * full result without truncation.  We avoid the small-then-retry
268	     * pattern because retrying would execute the tool twice, which is
269	     * wrong for write/mutating tools (write_file, cron_add, etc.). */
270	    size_t buf_size = agent_mem_safe_size(output_size, AGENT_STREAM_INIT_SIZE);
271	    char* buf = malloc(buf_size);
272	    if (buf) {
273	        buf[0] = '\0';
274	        tool_registry_execute(name, input_json, buf, buf_size);
275	        size_t result_len = strlen(buf);
276	        if (result_len >= output_size)
277	            result_len = output_size - 1;
278	        memcpy(output, buf, result_len);
279	        output[result_len] = '\0';
280	        free(buf);
281	        return (int)result_len;
282	    }
283	
284	    /* OOM fallback: execute directly into caller buffer */
285	    output[0] = '\0';
286	    tool_registry_execute(name, input_json, output, output_size);
287	    return (int)strlen(output);
288	}
