58	/* -- HTTP helpers ----------------------------------------------- */
59	
60	static void send_response(int fd, int code, const char* body)
61	{
62	    const char* status = (code == 200) ? "OK" : "Bad Request";
63	    char hdr[256];
64	    int hlen = snprintf(hdr, sizeof(hdr),
65	        "HTTP/1.1 %d %s\r\n"
66	        "Content-Type: application/json\r\n"
67	        "Content-Length: %d\r\n"
68	        "Connection: close\r\n\r\n",
69	        code, status, (int)strlen(body));
70	    send(fd, hdr, hlen, 0);
71	    send(fd, body, strlen(body), 0);
72	}
73	
74	static const char* find_body(const char* buf, int buf_len)
75	{
76	    const char* p = strstr(buf, "\r\n\r\n");
77	    return p ? p + 4 : NULL;
78	}
79	
80	/**
81	 * Read full HTTP body. peek_buf may contain partial body after headers.
82	 * Reads remaining bytes from fd based on Content-Length.
83	 * Returns malloc'd buffer (caller must free), or NULL on failure.
84	 */
85	static char* read_full_body(int fd, const char* buf, int buf_len)
86	{
87	    const char* hdr_end = strstr(buf, "\r\n\r\n");
88	    if (!hdr_end)
89	        return NULL;
90	    hdr_end += 4;
91	
92	    /* Find Content-Length */
93	    const char* cl = strcasestr(buf, "\r\nContent-Length: ");
94	    int content_len = cl ? atoi(cl + 18) : 0;
95	    if (content_len <= 0 || content_len > 32 * 1024) {
96	        /* No Content-Length or too large - use what's already in buffer */
97	        int already = buf_len - (int)(hdr_end - buf);
98	        if (already <= 0)
99	            return NULL;
100	        char* body = malloc(already + 1);
101	        if (!body)
102	            return NULL;
103	        memcpy(body, hdr_end, already);
104	        body[already] = '\0';
105	        return body;
106	    }
107	
108	    char* body = malloc(content_len + 1);
109	    if (!body)
110	        return NULL;
111	
112	    /* Copy what's already peeked */
113	    int already = buf_len - (int)(hdr_end - buf);
114	    if (already > content_len)
115	        already = content_len;
116	    if (already > 0)
117	        memcpy(body, hdr_end, already);
118	
119	    /* Read remaining from socket */
120	    int remaining = content_len - already;
121	    int offset = already;
122	    while (remaining > 0) {
123	        int n = recv(fd, body + offset, remaining, 0);
124	        if (n <= 0) {
125	            free(body);
126	            return NULL;
127	        }
128	        offset += n;
129	        remaining -= n;
130	    }
131	
132	    body[content_len] = '\0';
133	    return body;
134	}
