182	/**
183	 * Mask a secret value for display. Keeps the first and last 2 characters
184	 * and replaces the middle with "****" so the companion App can tell
185	 * whether a key is configured without exposing the actual secret over
186	 * the wire. Values of 4 characters or fewer are fully masked. An empty
187	 * value stays empty.
188	 */
189	static void mask_value(const char* in, char* out, size_t out_size)
190	{
191	    size_t len = in ? strlen(in) : 0;
192	    if (len == 0) {
193	        if (out_size > 0)
194	            out[0] = '\0';
195	        return;
196	    }
197	    if (len <= 4) {
198	        snprintf(out, out_size, "****");
199	        return;
200	    }
201	    snprintf(out, out_size, "%c%c****%c%c",
202	        in[0], in[1], in[len - 2], in[len - 1]);
203	}
