205	static bool handle_config_get(int fd)
206	{
207	    cJSON* obj = cJSON_CreateObject();
208	    char val[512];
209	    char masked[32];
210	
211	    /* Read llm_backend_0 and extract LLM fields */
212	    char backend_json[1024] = { 0 };
213	    cJSON* backend_obj = NULL;
214	    if (claw_config_get("llm_backend_0", backend_json, sizeof(backend_json)) == OK) {
215	        backend_obj = cJSON_Parse(backend_json);
216	    }
217	
218	    for (int i = 0; i < (int)NUM_CONFIG_KEYS; i++) {
219	        const char* backend_field = NULL;
220	        const char* raw = "";
221	        if (is_backend_key(s_config_keys[i], &backend_field) && backend_obj) {
222	            cJSON* item = cJSON_GetObjectItem(backend_obj, backend_field);
223	            raw = (item && cJSON_IsString(item)) ? item->valuestring : "";
224	        } else {
225	            val[0] = '\0';
226	            if (claw_config_get(s_config_keys[i], val, sizeof(val)) == OK)
227	                raw = val;
228	            else
229	                raw = "";
230	        }
231	
232	        if (is_secret_key(s_config_keys[i])) {
233	            mask_value(raw, masked, sizeof(masked));
234	            cJSON_AddStringToObject(obj, s_config_keys[i], masked);
235	        } else {
236	            cJSON_AddStringToObject(obj, s_config_keys[i], raw);
237	        }
238	    }
239	
240	    if (backend_obj)
241	        cJSON_Delete(backend_obj);
242	
243	    char* json = cJSON_PrintUnformatted(obj);
244	    cJSON_Delete(obj);
245	    if (!json) {
246	        send_response(fd, 500, "{\"error\":\"out of memory\"}");
247	        return true;
248	    }
249	
250	    send_response(fd, 200, json);
251	    free(json);
252	    return true;
253	}
