255	static bool handle_config_put(int fd, const char* body)
256	{
257	    syslog(LOG_INFO, "[%s] PUT /api/config body=%s\n", TAG,
258	        body ? body : "(null)");
259	
260	    if (!body || *body == '\0') {
261	        syslog(LOG_WARNING, "[%s] PUT config: empty body\n", TAG);
262	        send_response(fd, 400, "{\"error\":\"empty body\"}");
263	        return true;
264	    }
265	
266	    cJSON* req = cJSON_Parse(body);
267	    if (!req) {
268	        send_response(fd, 400, "{\"error\":\"invalid json\"}");
269	        return true;
270	    }
271	
272	    /* Collect backend field updates */
273	    bool backend_dirty = false;
274	    char backend_json[1024] = { 0 };
275	    claw_config_get("llm_backend_0", backend_json, sizeof(backend_json));
276	    cJSON* backend_obj = cJSON_Parse(backend_json);
277	    if (!backend_obj) {
278	        backend_obj = cJSON_CreateObject();
279	    }
280	
281	    cJSON* item = NULL;
282	    cJSON_ArrayForEach(item, req)
283	    {
284	        if (!cJSON_IsString(item) || !item->string) {
285	            continue;
286	        }
287	        /* Reject path traversal */
288	        if (strchr(item->string, '/') || strstr(item->string, "..")) {
289	            continue;
290	        }
291	
292	        /* Skip secret fields whose value is still the GET mask, so a
293	         * client that read masked values and PUTs the whole object back
294	         * does not overwrite the stored secret with "****".
295	         */
296	        if (is_secret_key(item->string) && item->valuestring
297	            && strstr(item->valuestring, "****")) {
298	            continue;
299	        }
300	
301	        const char* backend_field = NULL;
302	        if (is_backend_key(item->string, &backend_field)) {
303	            /* Update inside llm_backend_0 */
304	            cJSON_DeleteItemFromObject(backend_obj, backend_field);
305	            cJSON_AddStringToObject(backend_obj, backend_field, item->valuestring);
306	            backend_dirty = true;
307	            /* Also write flat key so config_show can display it */
308	            claw_config_set(item->string, item->valuestring);
309	        } else {
310	            /* Flat config key */
311	            claw_config_set(item->string, item->valuestring);
312	        }
313	    }
314	
315	    /* Persist backend changes */
316	    if (backend_dirty) {
317	        char* bstr = cJSON_PrintUnformatted(backend_obj);
318	        if (bstr) {
319	            claw_config_set("llm_backend_0", bstr);
320	            free(bstr);
321	        }
322	        /* Reload LLM router so changes take effect immediately */
323	        llm_router_init();
324	    }
325	
326	    cJSON_Delete(backend_obj);
327	    cJSON_Delete(req);
328	    send_response(fd, 200, "{\"ok\":true}");
329	    return true;
330	}
