334	static void url_decode(const char* src, char* dst, size_t dst_size)
335	{
336	    size_t di = 0;
337	    for (size_t si = 0; src[si] && di < dst_size - 1; si++) {
338	        if (src[si] == '%' && src[si + 1] && src[si + 2]) {
339	            char hex[3] = { src[si + 1], src[si + 2], 0 };
340	            dst[di++] = (char)strtol(hex, NULL, 16);
341	            si += 2;
342	        } else if (src[si] == '+') {
343	            dst[di++] = ' ';
344	        } else {
345	            dst[di++] = src[si];
346	        }
347	    }
348	    dst[di] = '\0';
349	}
