351	static bool handle_skills_get(int fd)
352	{
353	    cJSON* arr = cJSON_CreateArray();
354	    DIR* dir = opendir(AGENT_SKILLS_DIR);
355	
356	    if (dir) {
357	        struct dirent* ent;
358	        while ((ent = readdir(dir)) != NULL) {
359	            size_t nlen = strlen(ent->d_name);
360	            if (nlen < 4 || strcmp(ent->d_name + nlen - 3, ".md") != 0) {
361	                continue;
362	            }
363	
364	            /* Build full path */
365	            char path[256];
366	            snprintf(path, sizeof(path), "%s%s", AGENT_SKILLS_DIR,
367	                ent->d_name);
368	
369	            struct stat st;
370	            if (stat(path, &st) != 0) {
371	                continue;
372	            }
373	
374	            /* Extract name (without .md) */
375	            char name[128];
376	            snprintf(name, sizeof(name), "%.*s", (int)(nlen - 3),
377	                ent->d_name);
378	
379	            /* Try to read description and content */
380	            char desc[256] = "";
381	            char content[2048] = "";
382	            FILE* f = fopen(path, "r");
383	            if (f) {
384	                char line[256];
385	                bool in_front = false;
386	                int content_len = 0;
387	                while (fgets(line, sizeof(line), f)) {
388	                    if (strncmp(line, "---", 3) == 0) {
389	                        in_front = !in_front;
390	                        continue;
391	                    }
392	                    if (in_front && strncmp(line, "description:", 12) == 0) {
393	                        char* v = line + 12;
394	                        while (*v == ' ')
395	                            v++;
396	                        size_t vlen = strlen(v);
397	                        if (vlen > 0 && v[vlen - 1] == '\n')
398	                            v[vlen - 1] = '\0';
399	                        snprintf(desc, sizeof(desc), "%s", v);
400	                    }
401	                    /* Accumulate content */
402	                    size_t ll = strlen(line);
403	                    if (content_len + (int)ll < (int)sizeof(content) - 1) {
404	                        memcpy(content + content_len, line, ll);
405	                        content_len += (int)ll;
406	                    }
407	                }
408	                content[content_len] = '\0';
409	                fclose(f);
410	            }
411	
412	            cJSON* skill = cJSON_CreateObject();
413	            cJSON_AddStringToObject(skill, "name", name);
414	            cJSON_AddStringToObject(skill, "description", desc);
415	            cJSON_AddStringToObject(skill, "content", content);
416	            cJSON_AddStringToObject(skill, "file", ent->d_name);
417	            cJSON_AddNumberToObject(skill, "size", (double)st.st_size);
418	
419	            /* mtime as ISO string */
420	            struct tm tm;
421	            localtime_r(&st.st_mtime, &tm);
422	            char mtime[32];
423	            snprintf(mtime, sizeof(mtime), "%04d-%02d-%02dT%02d:%02d:%02d",
424	                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
425	                tm.tm_hour, tm.tm_min, tm.tm_sec);
426	            cJSON_AddStringToObject(skill, "mtime", mtime);
427	
428	            cJSON_AddItemToArray(arr, skill);
429	        }
430	        closedir(dir);
431	    }
432	
433	    cJSON* resp = cJSON_CreateObject();
434	    cJSON_AddItemToObject(resp, "skills", arr);
435	    char* json = cJSON_PrintUnformatted(resp);
436	    cJSON_Delete(resp);
437	
438	    if (!json) {
439	        send_response(fd, 500, "{\"error\":\"out of memory\"}");
440	        return true;
441	    }
442	
443	    send_response(fd, 200, json);
444	    free(json);
445	    return true;
446	}
