448	static bool handle_skills_post(int fd, const char* body)
449	{
450	    if (!body || *body == '\0') {
451	        send_response(fd, 400, "{\"error\":\"empty body\"}");
452	        return true;
453	    }
454	
455	    cJSON* req = cJSON_Parse(body);
456	    if (!req) {
457	        send_response(fd, 400, "{\"error\":\"invalid json\"}");
458	        return true;
459	    }
460	
461	    cJSON* name_item = cJSON_GetObjectItem(req, "name");
462	    cJSON* content_item = cJSON_GetObjectItem(req, "content");
463	
464	    if (!cJSON_IsString(name_item) || !cJSON_IsString(content_item)) {
465	        cJSON_Delete(req);
466	        send_response(fd, 400, "{\"error\":\"name and content required\"}");
467	        return true;
468	    }
469	
470	    const char* name = name_item->valuestring;
471	    const char* content = content_item->valuestring;
472	
473	    /* Validate name: no path traversal */
474	    if (strchr(name, '/') || strchr(name, '\\') || strstr(name, "..")) {
475	        cJSON_Delete(req);
476	        send_response(fd, 400, "{\"error\":\"invalid skill name\"}");
477	        return true;
478	    }
479	
480	    /* Write file */
481	    char path[256];
482	    snprintf(path, sizeof(path), "%s%s.md", AGENT_SKILLS_DIR, name);
483	
484	    FILE* f = fopen(path, "w");
485	    if (!f) {
486	        cJSON_Delete(req);
487	        send_response(fd, 500, "{\"error\":\"cannot write file\"}");
488	        return true;
489	    }
490	    fputs(content, f);
491	    fclose(f);
492	    cJSON_Delete(req);
493	
494	    /* Hot-reload skills */
495	    skill_loader_refresh();
496	
497	    syslog(LOG_INFO, "[%s] Skill pushed: %s\n", TAG, name);
498	    send_response(fd, 200, "{\"ok\":true}");
499	    return true;
500	}
