502	static bool handle_skills_delete(int fd, const char* name)
503	{
504	    if (!name || *name == '\0') {
505	        send_response(fd, 400, "{\"error\":\"skill name required\"}");
506	        return true;
507	    }
508	
509	    /* URL decode the name (browser/OkHttp encodes Chinese chars) */
510	    char decoded[128];
511	    url_decode(name, decoded, sizeof(decoded));
512	
513	    /* Validate name */
514	    if (strchr(decoded, '/') || strchr(decoded, '\\') || strstr(decoded, "..")) {
515	        send_response(fd, 400, "{\"error\":\"invalid skill name\"}");
516	        return true;
517	    }
518	
519	    char path[256];
520	    snprintf(path, sizeof(path), "%s%s.md", AGENT_SKILLS_DIR, decoded);
521	
522	    if (unlink(path) != 0 && errno != ENOENT) {
523	        send_response(fd, 500, "{\"error\":\"cannot delete file\"}");
524	        return true;
525	    }
526	
527	    skill_loader_refresh();
528	
529	    syslog(LOG_INFO, "[%s] Skill deleted: %s\n", TAG, decoded);
530	    send_response(fd, 200, "{\"ok\":true}");
531	    return true;
532	}
