573	bool api_try_handle(int fd, const char* buf, int buf_len)
574	{
575	    /* Quick check: must start with a valid HTTP method targeting /api/ */
576	    if (!buf || buf_len < 10) {
577	        return false;
578	    }
579	
580	    if (strncmp(buf, "GET /api/", 9) != 0 && strncmp(buf, "PUT /api/", 9) != 0 && strncmp(buf, "POST /api/", 10) != 0 && strncmp(buf, "DELETE /api/", 12) != 0) {
581	        return false;
582	    }
583	
584	    /* Parse method and path */
585	    char method[8] = "";
586	    char path[128] = "";
587	    sscanf(buf, "%7s %127s", method, path);
588	
589	    syslog(LOG_INFO, "[%s] api_try_handle: %s %s\n", TAG, method, path);
590	
591	    /* Route: /api/health */
592	    if (strcmp(path, "/api/health") == 0 && strcmp(method, "GET") == 0) {
593	        return handle_health_get(fd);
594	    }
595	
596	    /* Route: /api/config */
597	    if (strcmp(path, "/api/config") == 0) {
598	        if (strcmp(method, "GET") == 0) {
599	            return handle_config_get(fd);
600	        }
601	        if (strcmp(method, "PUT") == 0) {
602	            char* body = read_full_body(fd, buf, buf_len);
603	            bool ret = handle_config_put(fd, body);
604	            free(body);
605	            return ret;
606	        }
607	    }
608	
609	    /* Route: /api/skills */
610	    if (strcmp(path, "/api/skills") == 0) {
611	        if (strcmp(method, "GET") == 0) {
612	            return handle_skills_get(fd);
613	        }
614	        if (strcmp(method, "POST") == 0) {
615	            char* body = read_full_body(fd, buf, buf_len);
616	            bool ret = handle_skills_post(fd, body);
617	            free(body);
618	            return ret;
619	        }
620	    }
621	
622	    /* Route: /api/skills/{name} */
623	    if (strncmp(path, "/api/skills/", 12) == 0 && strcmp(method, "DELETE") == 0) {
624	        return handle_skills_delete(fd, path + 12);
625	    }
626	
627	    /* Route: /api/logs */
628	    if (strncmp(path, "/api/logs", 9) == 0 && strcmp(method, "GET") == 0) {
629	        return handle_logs_get(fd);
630	    }
631	
632	    return false;
633	}
