17	/* Microphone uplink: AUDCODEC capture -> binary WebSocket frames.
18	 *
19	 * One thread per stream. It owns the codec for as long as it runs, so the
20	 * bring-up commands (mic_test and friends) must not be used concurrently.
21	 */
22	
23	#include "channels/mic_stream.h"
24	#include "channels/ws_server.h"
25	#include "agent_compat.h"
26	#include "agent_config.h"
27	
28	#include "sf32lb_audcodec.h"
29	
30	#include <pthread.h>
31	#include <stdio.h>
32	#include <string.h>
33	#include <unistd.h>
34	
35	#ifdef CONFIG_SF32LB52_AUDCODEC
36	
37	/* 8462 Hz, G.711 mu-law, one byte per sample.
38	 *
39	 * Measured with `mic_rate 10 9 1` on this board: clk_div 9 / osr_sel 1
40	 * produces 8462 Hz.  A 60 s soak at this setting sustained 8.40 KB/s with
41	 * zero ping loss, and a 17.4 kHz 4-bit IMA ADPCM experiment showed that
42	 * 8.0-8.4 KB/s is the practical link ceiling (the tighter stream lost ~8%
43	 * of its samples).  This setting therefore keeps the wider 4.2 kHz band
44	 * while staying inside the link's reliable budget.
45	 *
46	 * The rate must be what the ADC actually produces, not a nominal value:
47	 * announcing anything else shifts the whole spectrum, which a recogniser
48	 * notices.  Re-measure with mic_rate after touching either divider.
49	 *
50	 * The delivered byte rate equals MIC_STREAM_RATE exactly while nothing is
51	 * dropped, so the receiver's byte counter is the check to make.
52	 */
53	
54	#define MIC_STREAM_RATE    8462
55	#define MIC_STREAM_CLK_DIV 9
56	#define MIC_STREAM_OSR_SEL 1
57	
58	/* The driver defaults to +30 dB, which saturates the on-board MEMS mic at
59	 * normal speaking distance (peak 32767 with hundreds of clipped samples).
60	 * 18 dB leaves headroom while keeping speech well above the ADC noise floor;
61	 * the host high-pass and ASR front end handle the rest. */
62	#define MIC_STREAM_VOLUME_DB 18
63	
64	static pthread_t s_thread;
65	static volatile bool s_running;
66	static bool s_started;
67	static char s_chat_id[64];
68	static int  s_samples = MIC_STREAM_DEF_SAMPLES;
69	
70	/* Static rather than stack: the streaming thread only needs a small stack,
71	 * and this keeps it that way.
72	 */
73	
74	static int16_t s_block[MIC_STREAM_MAX_SAMPLES];
75	static uint8_t s_encoded[MIC_STREAM_MAX_SAMPLES];
76	
77	/****************************************************************************
78	 * Name: mic_ulaw_encode
79	 *
80	 * Description:
81	 *   ITU-T G.711 mu-law companding. Quantisation is logarithmic because
82	 *   speech spends most of its time at low amplitude, and a linear 8-bit
83	 *   representation throws away the very part that carries the words.
84	 *
85	 ****************************************************************************/
86	
87	static uint8_t mic_ulaw_encode(int16_t pcm)
88	{
89	    const int bias = 0x84;
90	    const int clip = 32635;
91	    int sample = pcm;          /* int: -(-32768) has to fit */
92	    int sign = 0;
93	    int exponent = 7;
94	    int mantissa;
95	    int mask;
96	
97	    if (sample < 0) {
98	        sample = -sample;
99	        sign = 0x80;
100	    }
101	
102	    if (sample > clip) {
103	        sample = clip;
104	    }
105	
106	    sample += bias;
107	
108	    /* Segment count: how many bits below bit 14 are needed to reach the
109	     * leading one. */
110	    for (mask = 0x4000; exponent > 0 && (sample & mask) == 0; mask >>= 1) {
111	        exponent--;
112	    }
113	
114	    mantissa = (sample >> (exponent + 3)) & 0x0f;
115	
116	    return (uint8_t)(~(sign | (exponent << 4) | mantissa));
117	}
118	
119	static void* mic_stream_thread(void* arg)
120	{
121	    (void)arg;
122	
123	    syslog(LOG_INFO, "[mic_stream] capture starting for %s\n", s_chat_id);
124	
125	    /* Tell the far end what the bytes mean before sending any. A recogniser
126	     * fed the wrong rate or the wrong codec does not fail loudly, it just
127	     * produces confident nonsense, so the format travels with the stream. */
128	    {
129	        char fmt[96];
130	        snprintf(fmt, sizeof(fmt),
131	            "{\"type\":\"audio_format\",\"codec\":\"ulaw\",\"rate\":%d,"
132	            "\"channels\":1}", MIC_STREAM_RATE);
133	        ws_server_send_json(s_chat_id, fmt);
134	    }
135	
136	    /* Re-open so the requested clock dividers always take effect.  The
137	     * previous capture may have been started by mic_test/mic_rate with a
138	     * different divider pair; reusing it would silently stream at the old
139	     * rate while announcing the new one. */
140	    if (sf32lb_audcodec_is_open()) {
141	        sf32lb_audcodec_close();
142	        usleep(50000);
143	    }
144	
145	    sf32lb_audcodec_set_clk(MIC_STREAM_CLK_DIV, MIC_STREAM_OSR_SEL);
146	
147	    {
148	        int ret = sf32lb_audcodec_open_ex(MIC_STREAM_RATE,
149	                                          SF32LB_AUDIO_CLK_PLL, 0,
150	                                          MIC_STREAM_VOLUME_DB);
151	        if (ret < 0) {
152	            syslog(LOG_ERR, "[mic_stream] open failed (%d)\n", ret);
153	            s_running = false;
154	            return NULL;
155	        }
156	    }
157	
158	    while (s_running) {
159	        ssize_t n = sf32lb_audcodec_read(s_block, (size_t)s_samples);
160	        ssize_t i;
161	
162	        if (n < 0) {
163	            syslog(LOG_ERR, "[mic_stream] capture read failed (%d)\n", (int)n);
164	            break;
165	        }
166	
167	        for (i = 0; i < n; i++) {
168	            s_encoded[i] = mic_ulaw_encode(s_block[i]);
169	        }
170	
171	        /* A failed send means the client went away; stop rather than spin. */
172	        if (ws_server_send_binary(s_chat_id, s_encoded, (size_t)n) != OK) {
173	            syslog(LOG_WARNING, "[mic_stream] send failed, stopping\n");
174	            break;
175	        }
176	
177	    }
178	
179	    sf32lb_audcodec_close();
180	    s_running = false;
181	
182	    syslog(LOG_INFO, "[mic_stream] capture stopped\n");
183	    return NULL;
184	}
185	
186	int mic_stream_start(const char* chat_id, int samples)
187	{
188	    if (s_running) {
189	        return OK; /* already streaming */
190	    }
191	
192	    if (chat_id == NULL || chat_id[0] == '\0') {
193	        return ERROR;
194	    }
195	
196	    if (samples <= 0) {
197	        samples = MIC_STREAM_DEF_SAMPLES;
198	    } else if (samples > MIC_STREAM_MAX_SAMPLES) {
199	        samples = MIC_STREAM_MAX_SAMPLES;
200	    }
201	
202	    s_samples = samples;
203	
204	    strncpy(s_chat_id, chat_id, sizeof(s_chat_id) - 1);
205	    s_chat_id[sizeof(s_chat_id) - 1] = '\0';
206	
207	    syslog(LOG_INFO, "[mic_stream] chunk = %d samples (%d bytes)\n",
208	        s_samples, s_samples * 2);
209	
210	    s_running = true;
211	
212	    pthread_attr_t attr;
213	    pthread_attr_init(&attr);
214	    pthread_attr_setstacksize(&attr, AGENT_MIC_STREAM_STACK);
215	
216	    int ret = pthread_create(&s_thread, &attr, mic_stream_thread, NULL);
217	    pthread_attr_destroy(&attr);
218	
219	    if (ret != 0) {
220	        s_running = false;
221	        syslog(LOG_ERR, "[mic_stream] pthread_create failed (%d)\n", ret);
222	        return ERROR;
223	    }
224	
225	    s_started = true;
226	    return OK;
227	}
228	
229	int mic_stream_stop(void)
230	{
231	    if (!s_running && !s_started) {
232	        return OK;
233	    }
234	
235	    s_running = false;
236	
237	    /* The thread notices s_running within one 100 ms block. */
238	    pthread_join(s_thread, NULL);
239	    s_started = false;
240	
241	    return OK;
242	}
243	
244	bool mic_stream_is_running(void)
245	{
246	    return s_running;
247	}
248	
249	int mic_stream_set_volume(int volume_db)
250	{
251	    return sf32lb_audcodec_set_volume(volume_db);
252	}
253	
254	#else /* !CONFIG_SF32LB52_AUDCODEC */
255	
256	int mic_stream_start(const char* chat_id, int samples)
257	{
258	    (void)chat_id;
259	    (void)samples;
260	    return ERROR;
261	}
262	
263	int mic_stream_stop(void)
264	{
265	    return OK;
266	}
267	
268	bool mic_stream_is_running(void)
269	{
270	    return false;
271	}
272	
273	int mic_stream_set_volume(int volume_db)
274	{
275	    (void)volume_db;
276	    return ERROR;
277	}
