57	static const char* TAG = "ws";
58	
59	/* ── WS Magic GUID ────────────────────────────────────────────── */
60	
61	#define WS_GUID "258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
62	
63	/* ── Client table ─────────────────────────────────────────────── */
64	
65	/* Size of the per-client scratch used to coalesce a frame's header and
66	 * payload into a single send(). 2 KB covers an audio frame (the stream caps
67	 * at 1024 samples) with room to spare; anything larger falls back to a heap
68	 * buffer. It is per-client rather than shared because two clients are
69	 * written concurrently by different threads now that sending no longer
70	 * serialises globally. */
71	#define WS_FRAME_SCRATCH 2048
72	
73	typedef struct {
74	    int fd;
75	    char chat_id[32];
76	    bool active;
77	
78	    /* Serialises frames on THIS client's socket.
79	     *
80	     * It used to be one mutex for every client, held across the send itself.
81	     * A send is a blocked send for as long as the frame takes to shift over
82	     * a ~6 KB/s link, so one peer that stopped reading -- or just a busy one
83	     * -- parked that mutex inside send() and starved every other writer:
84	     * the microphone stream, agent replies, and the pong that answers the
85	     * far end's keepalive. Losing the pong drops the session, and losing the
86	     * stream stalls the demo, both caused by a third party doing nothing
87	     * wrong. Per-client means a slow peer only slows itself.
88	     *
89	     * Lock order is always table-lock then client-lock; that is the only
90	     * order taken anywhere, so it cannot deadlock.
91	     */
92	    pthread_mutex_t tx_mtx;
93	    unsigned char   scratch[WS_FRAME_SCRATCH];
94	} ws_client_t;
95	
96	static ws_client_t s_clients[AGENT_WS_MAX_CLIENTS];
97	static pthread_mutex_t s_clients_mtx = PTHREAD_MUTEX_INITIALIZER;
98	static bool s_tx_mtx_ready = false;
99	
100	static int s_listen_fd = -1;
101	static volatile bool s_running = false;
102	
103	/* ── Client helpers ───────────────────────────────────────────── */
104	
105	/* Call with s_clients_mtx held. */
106	static ws_client_t* find_by_fd_locked(int fd)
107	{
108	    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
109	        if (s_clients[i].active && s_clients[i].fd == fd)
110	            return &s_clients[i];
111	    }
112	    return NULL;
113	}
114	
115	/* Call with s_clients_mtx held. */
116	static ws_client_t* find_by_chat_id_locked(const char* chat_id)
117	{
118	    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
119	        if (s_clients[i].active && strcmp(s_clients[i].chat_id, chat_id) == 0)
120	            return &s_clients[i];
121	    }
122	    return NULL;
123	}
124	
125	/* Hold a client's transmit lock, or NULL if it is not there.
126	 *
127	 * The table lock is taken only long enough to find the entry and claim its
128	 * transmit lock. Holding it across the send instead is what let one slow
129	 * peer stall the whole server; holding it only for the lookup means the
130	 * table can still be read and written while a frame is going out -- which
131	 * is why the transmit lock has to be claimed here, before the table lock is
132	 * released: otherwise the entry could be removed and its fd closed and
133	 * reused underneath the sender.
134	 */
135	static ws_client_t* lock_client_for_send(const char* chat_id)
136	{
137	    ws_client_t* client;
138	
139	    pthread_mutex_lock(&s_clients_mtx);
140	    client = find_by_chat_id_locked(chat_id);
141	    if (client != NULL) {
142	        pthread_mutex_lock(&client->tx_mtx);
143	    }
144	    pthread_mutex_unlock(&s_clients_mtx);
145	
146	    return client;
147	}
148	
149	static ws_client_t* lock_client_by_fd(int fd)
150	{
151	    ws_client_t* client;
152	
153	    pthread_mutex_lock(&s_clients_mtx);
154	    client = find_by_fd_locked(fd);
155	    if (client != NULL) {
156	        pthread_mutex_lock(&client->tx_mtx);
157	    }
158	    pthread_mutex_unlock(&s_clients_mtx);
159	
160	    return client;
161	}
162	
163	static void unlock_client(ws_client_t* client)
164	{
165	    if (client != NULL) {
166	        pthread_mutex_unlock(&client->tx_mtx);
167	    }
168	}
169	
170	static ws_client_t* add_client_locked(int fd)
171	{
172	    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
173	        if (!s_clients[i].active) {
174	            s_clients[i].fd = fd;
175	            s_clients[i].active = true;
176	            snprintf(s_clients[i].chat_id, sizeof(s_clients[i].chat_id), "ws_%d", fd);
177	            syslog(LOG_INFO, "[%s] Client connected: %s (fd=%d)\n", TAG,
178	                s_clients[i].chat_id, fd);
179	            return &s_clients[i];
180	        }
181	    }
182	    return NULL;
183	}
184	
185	static void remove_client_locked(int fd)
186	{
187	    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
188	        if (s_clients[i].active && s_clients[i].fd == fd) {
189	            syslog(LOG_INFO, "[%s] Client disconnected: %s\n", TAG,
190	                s_clients[i].chat_id);
191	
192	            /* Wait for a send that is already in flight before closing, or
193	             * the fd could be closed and handed to something else while the
194	             * sender still writes to it. Same lock order as the send path. */
195	            pthread_mutex_lock(&s_clients[i].tx_mtx);
196	            s_clients[i].active = false;
197	            s_clients[i].fd = -1; /* invalidate fd before closing */
198	            pthread_mutex_unlock(&s_clients[i].tx_mtx);
199	
200	            close(fd);
201	            return;
202	        }
203	    }
204	}
205	
206	/* ── WS handshake ─────────────────────────────────────────────── */
207	
208	/**
209	 * Compute Sec-WebSocket-Accept = base64(SHA1(key + GUID))
210	 */
211	static int make_accept_key(const char* key, char* out, size_t out_size)
212	{
213	    char combined[256];
214	    int clen = snprintf(combined, sizeof(combined), "%s%s", key, WS_GUID);
215	    if (clen <= 0 || clen >= (int)sizeof(combined))
216	        return -1;
217	
218	    unsigned char sha[20];
219	    if (mbedtls_sha1((const unsigned char*)combined, (size_t)clen, sha) != 0)
220	        return -1;
221	
222	    size_t written = 0;
223	    if (mbedtls_base64_encode((unsigned char*)out, out_size, &written, sha,
224	            sizeof(sha))
225	        != 0)
226	        return -1;
227	    out[written] = '\0';
228	    return (int)written;
229	}
230	
231	/**
232	 * WebSocket handshake using pre-read buffer.
233	 * Read full HTTP upgrade request, extract Sec-WebSocket-Key.
234	 * Returns 0 on success; sends 101 response.
235	 */
236	static int do_ws_handshake_ex(int fd, const char* buf, int buf_len,
237	    char* chat_id_out, size_t chat_id_size)
238	{
239	
240	    /* Extract Sec-WebSocket-Key */
241	    char* key_hdr = strcasestr(buf, "\r\nSec-WebSocket-Key: ");
242	    if (!key_hdr) {
243	        syslog(LOG_WARNING, "[%s] No Sec-WebSocket-Key\n", TAG);
244	        return -1;
245	    }
246	    key_hdr += 21;
247	    char* eol = strstr(key_hdr, "\r\n");
248	    if (!eol)
249	        return -1;
250	
251	    char ws_key[128] = { 0 };
252	    size_t klen = (size_t)(eol - key_hdr);
253	    if (klen >= sizeof(ws_key))
254	        return -1;
255	    memcpy(ws_key, key_hdr, klen);
256	    ws_key[klen] = '\0';
257	
258	    /* Compute accept */
259	    char accept[64] = { 0 };
260	    if (make_accept_key(ws_key, accept, sizeof(accept)) < 0)
261	        return -1;
262	
263	    /* Send 101 */
264	    char resp[512];
265	    int rlen = snprintf(resp, sizeof(resp),
266	        "HTTP/1.1 101 Switching Protocols\r\n"
267	        "Upgrade: websocket\r\n"
268	        "Connection: Upgrade\r\n"
269	        "Sec-WebSocket-Accept: %s\r\n\r\n",
270	        accept);
271	    if (send(fd, resp, rlen, 0) != rlen)
272	        return -1;
273	
274	    /* Default chat_id from fd (may be overridden by first message) */
275	    snprintf(chat_id_out, chat_id_size, "ws_%d", fd);
276	    return 0;
277	}
278	
279	/* ── WS frame encode/decode ───────────────────────────────────── */
280	
281	/* Opcodes this server emits. Incoming frames are decoded separately. */
282	#define WS_OPCODE_TEXT   0x1
283	#define WS_OPCODE_BINARY 0x2
284	
285	/**
286	 * Send one unfragmented frame (server → client, no masking).
287	 * Caller must hold the client's tx_mtx, which also covers its scratch.
288	 */
289	static int ws_send_frame_op(ws_client_t* client, const void* payload,
290	    size_t len, int opcode)
291	{
292	    unsigned char hdr[10];
293	    int hdr_len = 0;
294	    int fd = client->fd;
295	
296	    hdr[0] = (unsigned char)(0x80 | opcode); /* FIN + opcode */
297	    if (len < 126) {
298	        hdr[1] = (unsigned char)len;
299	        hdr_len = 2;
300	    } else if (len < 65536) {
301	        hdr[1] = 126;
302	        hdr[2] = (unsigned char)(len >> 8);
303	        hdr[3] = (unsigned char)(len & 0xFF);
304	        hdr_len = 4;
305	    } else {
306	        syslog(LOG_ERR, "[%s] Payload too large: %d\n", TAG, (int)len);
307	        return -1;
308	    }
309	
310	    /* Header and payload go out in a single send().
311	     *
312	     * Emitting them separately makes Nagle hold the payload back until the
313	     * header is acknowledged, while the peer's delayed ACK waits for a second
314	     * segment before acknowledging -- the two together stall each frame for
315	     * roughly the delayed-ACK timer. On a microphone stream that is fatal:
316	     * at 100 ms per frame it throttles delivery to about a third of the
317	     * capture rate, and the samples the reader never gets to are silently
318	     * overwritten by the DMA.
319	     */
320	    if (hdr_len + len <= sizeof(client->scratch))
321	      {
322	        memcpy(client->scratch, hdr, hdr_len);
323	        memcpy(client->scratch + hdr_len, payload, len);
324	        if (send(fd, client->scratch, hdr_len + len, 0) != hdr_len + (int)len)
325	          {
326	            return -1;
327	          }
328	
329	        return 0;
330	      }
331	
332	    /* Larger frames: still one send(), from the heap. Never two sends -- see
333	     * the note above about interleaving with other writers. */
334	    unsigned char* big = malloc(hdr_len + len);
335	    if (big == NULL)
336	      {
337	        syslog(LOG_ERR, "[%s] out of memory for %d byte frame\n", TAG,
338	            (int)(hdr_len + len));
339	        return -1;
340	      }
341	
342	    memcpy(big, hdr, hdr_len);
343	    memcpy(big + hdr_len, payload, len);
344	    int rc = (send(fd, big, hdr_len + len, 0) == hdr_len + (int)len) ? 0 : -1;
345	    free(big);
346	    return rc;
347	}
348	
349	/**
350	 * Send a text frame. Caller must hold the client's tx_mtx.
351	 */
352	static int ws_send_frame(ws_client_t* client, const char* payload, size_t len)
353	{
354	    return ws_send_frame_op(client, payload, len, WS_OPCODE_TEXT);
355	}
356	
357	/**
358	 * Read and decode one WS frame; place text payload into buf (NUL-terminated).
359	 * Returns payload length on success, 0 on close frame, -1 on error.
360	 */
361	static int ws_recv_frame(int fd, char* buf, size_t buf_size)
362	{
363	    unsigned char b0, b1;
364	    if (recv(fd, &b0, 1, MSG_WAITALL) != 1)
365	        return -1;
366	    if (recv(fd, &b1, 1, MSG_WAITALL) != 1)
367	        return -1;
368	
369	    int opcode = b0 & 0x0F;
370	    bool masked = (b1 & 0x80) != 0;
371	    size_t plen = b1 & 0x7F;
372	
373	    if (opcode == 0x8)
374	        return 0; /* Close frame */
375	
376	    if (opcode == 0x9 || opcode == 0xA) {
377	        /* Ping (0x9) or Pong (0xA) — must consume payload before returning,
378	         * otherwise leftover bytes corrupt the next frame read. */
379	        if (plen == 126) {
380	            unsigned char ext[2];
381	            if (recv(fd, ext, 2, MSG_WAITALL) != 2)
382	                return -1;
383	            plen = ((size_t)ext[0] << 8) | ext[1];
384	        } else if (plen == 127) {
385	            return -1;
386	        }
387	
388	        unsigned char pp_mask[4] = { 0 };
389	        if (masked) {
390	            if (recv(fd, pp_mask, 4, MSG_WAITALL) != 4)
391	                return -1;
392	        }
393	
394	        if (plen > 125) {
395	            syslog(LOG_ERR,
396	                "[%s] Invalid control frame payload length: %d\n",
397	                TAG, (int)plen);
398	            return -1;
399	        }
400	
401	        /* Read full control payload so ping can be echoed in pong. */
402	        unsigned char ctrl_payload[125] = { 0 };
403	        if (plen > 0) {
404	            if (recv(fd, ctrl_payload, plen, MSG_WAITALL) != (int)plen)
405	                return -1;
406	
407	            if (masked) {
408	                for (size_t i = 0; i < plen; i++) {
409	                    ctrl_payload[i] ^= pp_mask[i % 4];
410	                }
411	            }
412	        }
413	
414	        /* Reply with pong if it was a ping.
415	         *
416	         * Assembled into one buffer and sent holding this client's transmit
417	         * lock: this runs on the client thread while other threads (the
418	         * microphone stream, agent replies) write to the same socket, and a
419	         * control frame that lands between another frame's header and its
420	         * payload desynchronises the peer's parser. Coalescing also avoids
421	         * the same Nagle/delayed-ACK stall that splitting a frame across two
422	         * sends causes.
423	         *
424	         * This is the send that used to be the most expensive to delay: the
425	         * far end treats a late pong as a dead connection and drops a
426	         * session that is working perfectly.
427	         */
428	        if (opcode == 0x9) {
429	            unsigned char pong[2 + 125];
430	            size_t n = 0;
431	
432	            pong[n++] = 0x8A;
433	            pong[n++] = (unsigned char)plen;
434	            if (plen > 0) {
435	                memcpy(pong + n, ctrl_payload, plen);
436	                n += plen;
437	            }
438	
439	            ws_client_t* c = lock_client_by_fd(fd);
440	            if (c != NULL) {
441	                send(fd, pong, n, 0);
442	                unlock_client(c);
443	            }
444	        }
445	        return -2;
446	    }
447	
448	    if (opcode != 0x1 && opcode != 0x2) {
449	        /* Unknown opcode — skip */
450	        return -2;
451	    }
452	
453	    if (plen == 126) {
454	        unsigned char ext[2];
455	        if (recv(fd, ext, 2, MSG_WAITALL) != 2)
456	            return -1;
457	        plen = ((size_t)ext[0] << 8) | ext[1];
458	    } else if (plen == 127) {
459	        syslog(LOG_ERR, "[%s] 64-bit frame length not supported\n", TAG);
460	        return -1;
461	    }
462	
463	    unsigned char mask_key[4] = { 0 };
464	    if (masked) {
465	        if (recv(fd, mask_key, 4, MSG_WAITALL) != 4)
466	            return -1;
467	    }
468	
469	    if (plen >= buf_size) {
470	        syslog(LOG_ERR, "[%s] Frame too large: %d\n", TAG, (int)plen);
471	        return -1;
472	    }
473	
474	    int received = 0;
475	    while ((size_t)received < plen) {
476	        int n = recv(fd, buf + received, plen - received, 0);
477	        if (n <= 0)
478	            return -1;
479	        received += n;
480	    }
481	
482	    if (masked) {
483	        for (size_t i = 0; i < plen; i++) {
484	            ((unsigned char*)buf)[i] ^= mask_key[i % 4];
485	        }
486	    }
487	
488	    buf[plen] = '\0';
489	    return (int)plen;
490	}
491	
492	/* ── Per-client thread ────────────────────────────────────────── */
493	
494	typedef struct {
495	    int fd;
496	} client_arg_t;
497	
498	/* How long a send to one client may block before it is treated as failed.
499	 *
500	 * A healthy peer drains in milliseconds -- the worst real frame is a few KB
501	 * over a ~6 KB/s link, so a few hundred of them -- and anything approaching
502	 * this is a peer that has stopped reading or vanished without the socket
503	 * noticing. Without a bound, send() parks for as long as the stack takes to
504	 * give up, and a blocked send sits inside the network lock: one stalled peer
505	 * then stops the microphone stream and every other socket on the device,
506	 * which is exactly what a load test with a silent client reproduced. With
507	 * it, the frame fails, the client is dropped, and the rest carries on.
508	 */
509	#define WS_SEND_TIMEOUT_S 5
510	
511	static void* client_thread(void* arg)
512	{
513	    client_arg_t ca = *(client_arg_t*)arg;
514	    free(arg);
515	    int fd = ca.fd;
516	
517	    {
518	        struct timeval tv;
519	        tv.tv_sec = WS_SEND_TIMEOUT_S;
520	        tv.tv_usec = 0;
521	        if (setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv)) < 0) {
522	            syslog(LOG_WARNING, "[%s] fd=%d: SO_SNDTIMEO not set (%d)\n",
523	                TAG, fd, errno);
524	        }
525	    }
526	
527	    /* Peek HTTP headers to decide: REST API or WebSocket */
528	    char* peek_buf = malloc(2048);
529	    if (!peek_buf) {
530	        close(fd);
531	        return NULL;
532	    }
533	    int peek_total = 0;
534	    while (peek_total < 2048 - 1) {
535	        int n = recv(fd, peek_buf + peek_total,
536	            2048 - 1 - peek_total, 0);
537	        if (n <= 0) {
538	            free(peek_buf);
539	            close(fd);
540	            return NULL;
541	        }
542	        peek_total += n;
543	        peek_buf[peek_total] = '\0';
544	        if (strstr(peek_buf, "\r\n\r\n"))
545	            break;
546	    }
547	
548	    syslog(LOG_INFO, "[%s] fd=%d: %d bytes, first line: %.60s\n", TAG, fd,
549	        peek_total, peek_buf);
550	
551	    /* Try REST API (config/skills/logs) */
552	#ifdef CONFIG_AI_AGENT_REST_API
553	    if (api_try_handle(fd, peek_buf, peek_total)) {
554	        free(peek_buf);
555	        /* Graceful close only. SO_LINGER with l_linger=0 here used to send
556	         * an RST that discarded the response still in the send buffer,
557	         * so REST clients saw "Connection reset by peer" and no body. */
558	        shutdown(fd, SHUT_WR);
559	        close(fd);
560	        return NULL;
561	    }
562	#endif
563	
564	    /* Not REST API - proceed with WebSocket handshake using pre-read buffer */
565	    char chat_id[32];
566	    if (do_ws_handshake_ex(fd, peek_buf, peek_total,
567	            chat_id, sizeof(chat_id))
568	        != 0) {
569	        syslog(LOG_WARNING, "[%s] Handshake failed for fd=%d\n", TAG, fd);
570	        free(peek_buf);
571	        /* Answer plain-HTTP callers with a 400 instead of a silent close,
572	         * so the client sees a real response instead of a bare FIN/RST. */
573	        static const char bad[] =
574	            "HTTP/1.1 400 Bad Request\r\n"
575	            "Content-Type: text/plain\r\n"
576	            "Content-Length: 20\r\n"
577	            "Connection: close\r\n\r\n"
578	            "not a WebSocket peer\n";
579	        send(fd, bad, sizeof(bad) - 1, 0);
580	        shutdown(fd, SHUT_WR);
581	        close(fd);
582	        return NULL;
583	    }
584	    free(peek_buf);
585	
586	    /* Register client */
587	    pthread_mutex_lock(&s_clients_mtx);
588	    ws_client_t* client = add_client_locked(fd);
589	    if (!client) {
590	        pthread_mutex_unlock(&s_clients_mtx);
591	        syslog(LOG_WARNING, "[%s] Max clients reached, closing fd=%d\n", TAG, fd);
592	        /* Politely close */
593	        unsigned char close_frame[2] = { 0x88, 0x00 };
594	        send(fd, close_frame, 2, 0);
595	        close(fd);
596	        return NULL;
597	    }
598	    snprintf(client->chat_id, sizeof(client->chat_id), "%s", chat_id);
599	    pthread_mutex_unlock(&s_clients_mtx);
600	
601	    /* Send connect.challenge so Nodes can identify themselves */
602	#ifdef CONFIG_AI_AGENT_NODE
603	    node_manager_send_challenge(fd);
604	#endif
605	
606	    /* Read loop — stack-allocated so each client thread has its own buffer */
607	    char frame_buf[4096];
608	    while (s_running) {
609	        int n = ws_recv_frame(fd, frame_buf, sizeof(frame_buf));
610	        if (n < 0 && n != -2)
611	            break; /* -2 = ignored opcode, not an error */
612	        if (n == 0)
613	            break; /* clean close */
614	        if (n < 0)
615	            continue; /* ignored frame */
616	
617	        /* Try Node protocol first — if handled, skip chat processing */
618	#ifdef CONFIG_AI_AGENT_NODE
619	        if (node_manager_handle_message(fd, frame_buf, n))
620	            continue;
621	#endif
622	
623	        /* Parse JSON message */
624	        cJSON* root = cJSON_Parse(frame_buf);
625	        if (!root) {
626	            syslog(LOG_WARNING, "[%s] Invalid JSON from fd=%d (%d bytes): %.200s\n",
627	                TAG, fd, n, frame_buf);
628	            continue;
629	        }
630	
631	        cJSON* type_item = cJSON_GetObjectItem(root, "type");
632	        cJSON* content_item = cJSON_GetObjectItem(root, "content");
633	
634	        /* Microphone streaming control. These frames carry no content; they
635	         * switch this client's capture stream on and off. The reply, if any,
636	         * arrives asynchronously as binary PCM frames plus normal agent
637	         * responses.
638	         */
639	        if (cJSON_IsString(type_item)
640	            && (strcmp(type_item->valuestring, "mic_start") == 0
641	                || strcmp(type_item->valuestring, "mic_stop") == 0)) {
642	            bool want = (strcmp(type_item->valuestring, "mic_start") == 0);
643	            cJSON* n_item = cJSON_GetObjectItem(root, "samples");
644	            int samples = cJSON_IsNumber(n_item) ? (int)n_item->valuedouble : 0;
645	            syslog(LOG_INFO, "[%s] %s request from %s\n", TAG,
646	                type_item->valuestring, chat_id);
647	            cJSON_Delete(root);
648	            if (want)
649	                mic_stream_start(chat_id, samples);
650	            else
651	                mic_stream_stop();
652	            continue;
653	        }
654	
655	        /* UI-only notice from the host (wake armed, nothing recognised,
656	         * link status). It must not enter the agent bus: doing so used to
657	         * run a full LLM turn for every hint. Posting it to the UI queue
658	         * also clears the PTT "processing" latch, which is why the host
659	         * sends these notices in the first place. */
660	        if (cJSON_IsString(type_item)
661	            && strcmp(type_item->valuestring, "ui_notice") == 0
662	            && cJSON_IsString(content_item)) {
663	#ifdef CONFIG_AI_AGENT_LVGL_UI
664	            lvgl_ui_channel_post(content_item->valuestring);
665	#endif
666	            cJSON_Delete(root);
667	            continue;
668	        }
669	
670	        if (cJSON_IsString(type_item) && strcmp(type_item->valuestring, "message") == 0 && cJSON_IsString(content_item)) {
671	
672	            /* Determine/update chat_id */
673	            cJSON* cid_item = cJSON_GetObjectItem(root, "chat_id");
674	            pthread_mutex_lock(&s_clients_mtx);
675	            ws_client_t* c = find_by_fd_locked(fd);
676	            if (c) {
677	                if (cJSON_IsString(cid_item)) {
678	                    strncpy(c->chat_id, cid_item->valuestring, sizeof(c->chat_id) - 1);
679	                }
680	                strncpy(chat_id, c->chat_id, sizeof(chat_id) - 1);
681	            }
682	            pthread_mutex_unlock(&s_clients_mtx);
683	
684	            syslog(LOG_INFO, "[%s] WS msg from %s: %.40s\n", TAG, chat_id,
685	                content_item->valuestring);
686	
687	            agent_msg_t msg = { 0 };
688	            strncpy(msg.channel, AGENT_CHAN_WEBSOCKET, sizeof(msg.channel) - 1);
689	            strncpy(msg.chat_id, chat_id, sizeof(msg.chat_id) - 1);
690	            msg.content = strdup(content_item->valuestring);
691	            if (msg.content)
692	                message_bus_push_inbound(&msg);
693	        }
694	        cJSON_Delete(root);
695	    }
696	
697	    /* Notify node manager before removing client */
698	#ifdef CONFIG_AI_AGENT_NODE
699	    node_manager_on_disconnect(fd);
700	#endif
701	
702	    /* Remove and close */
703	    pthread_mutex_lock(&s_clients_mtx);
704	    remove_client_locked(fd);
705	    pthread_mutex_unlock(&s_clients_mtx);
706	
707	    return NULL;
708	}
709	
710	/* ── Accept loop ──────────────────────────────────────────────── */
711	
712	static void* accept_thread(void* arg)
713	{
714	    (void)arg;
715	    while (s_running) {
716	        struct pollfd pfd = { .fd = s_listen_fd, .events = POLLIN };
717	        int pr = poll(&pfd, 1, 500);
718	        if (pr <= 0)
719	            continue;
720	
721	        struct sockaddr_in addr;
722	        socklen_t addr_len = sizeof(addr);
723	        int cfd = accept(s_listen_fd, (struct sockaddr*)&addr, &addr_len);
724	        if (cfd < 0)
725	            continue;
726	
727	        syslog(LOG_INFO, "[%s] accepted fd=%d from %s:%d\n", TAG, cfd,
728	            inet_ntoa(addr.sin_addr), ntohs(addr.sin_port));
729	
730	        client_arg_t* ca = malloc(sizeof(client_arg_t));
731	        if (!ca) {
732	            close(cfd);
733	            continue;
734	        }
735	        ca->fd = cfd;
736	
737	        pthread_t tid;
738	        pthread_attr_t attr;
739	        pthread_attr_init(&attr);
740	        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
741	        pthread_attr_setstacksize(&attr, AGENT_WS_CLIENT_STACK);
742	        if (pthread_create(&tid, &attr, client_thread, ca) != 0) {
743	            free(ca);
744	            close(cfd);
745	        }
746	        pthread_attr_destroy(&attr);
747	    }
748	    return NULL;
749	}
