753	int ws_server_start(void)
754	{
755	    /* The transmit mutexes live in the table, so the table cannot simply be
756	     * memset() on a restart -- that would zero live mutexes. Re-initialising
757	     * them is equally wrong, so first time round zero the table and create
758	     * them; after that, clear only the fields that describe the connection. */
759	    if (!s_tx_mtx_ready) {
760	        memset(s_clients, 0, sizeof(s_clients));
761	        for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
762	            pthread_mutex_init(&s_clients[i].tx_mtx, NULL);
763	        }
764	        s_tx_mtx_ready = true;
765	    } else {
766	        for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
767	            s_clients[i].fd = -1;
768	            s_clients[i].active = false;
769	            s_clients[i].chat_id[0] = '\0';
770	        }
771	    }
772	
773	    s_listen_fd = socket(AF_INET, SOCK_STREAM, 0);
774	    if (s_listen_fd < 0) {
775	        syslog(LOG_ERR, "[%s] socket() failed\n", TAG);
776	        return ERROR;
777	    }
778	
779	    int opt = 1;
780	    setsockopt(s_listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
781	
782	    struct sockaddr_in addr = {
783	        .sin_family = AF_INET,
784	        .sin_port = htons(AGENT_WS_PORT),
785	        .sin_addr.s_addr = INADDR_ANY,
786	    };
787	
788	    if (bind(s_listen_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
789	        syslog(LOG_ERR, "[%s] bind() failed on port %d, errno=%d\n", TAG,
790	            AGENT_WS_PORT, errno);
791	        close(s_listen_fd);
792	        s_listen_fd = -1;
793	        return ERROR;
794	    }
795	
796	    if (listen(s_listen_fd, AGENT_WS_MAX_CLIENTS) < 0) {
797	        syslog(LOG_ERR, "[%s] listen() failed\n", TAG);
798	        close(s_listen_fd);
799	        s_listen_fd = -1;
800	        return ERROR;
801	    }
802	
803	    s_running = true;
804	
805	    pthread_t tid;
806	    pthread_attr_t attr;
807	    pthread_attr_init(&attr);
808	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
809	    pthread_attr_setstacksize(&attr, AGENT_CLI_STACK);
810	    int rc = pthread_create(&tid, &attr, accept_thread, NULL);
811	    pthread_attr_destroy(&attr);
812	
813	    if (rc != 0) {
814	        syslog(LOG_ERR, "[%s] Failed to create accept thread\n", TAG);
815	        s_running = false;
816	        close(s_listen_fd);
817	        s_listen_fd = -1;
818	        return ERROR;
819	    }
820	
821	    syslog(LOG_INFO, "[%s] WebSocket server started on port %d\n", TAG,
822	        AGENT_WS_PORT);
823	    return OK;
824	}
