826	static int ws_server_send_typed(const char* chat_id, const char* text,
827	                                const char* type)
828	{
829	    if (s_listen_fd < 0 || !s_running)
830	        return ERROR;
831	
832	    /* Build JSON response */
833	    cJSON* resp = cJSON_CreateObject();
834	    cJSON_AddStringToObject(resp, "type", type);
835	    cJSON_AddStringToObject(resp, "content", text);
836	    cJSON_AddStringToObject(resp, "chat_id", chat_id);
837	    char* json_str = cJSON_PrintUnformatted(resp);
838	    cJSON_Delete(resp);
839	    if (!json_str)
840	        return ERROR;
841	
842	    ws_client_t* client = lock_client_for_send(chat_id);
843	    int rc = -1;
844	    if (client) {
845	        rc = ws_send_frame(client, json_str, strlen(json_str));
846	        if (rc != 0) {
847	            syslog(
848	                LOG_WARNING,
849	                "[%s] Send failed to %s (fd will be cleaned up by client thread)\n",
850	                TAG, chat_id);
851	            /* Don't remove/close here — the client_thread owns the fd lifecycle.
852	             * The recv() in client_thread will fail and trigger cleanup. */
853	        }
854	        unlock_client(client);
855	    } else {
856	        syslog(LOG_WARNING, "[%s] No WS client for chat_id=%s\n", TAG, chat_id);
857	    }
858	
859	    free(json_str);
860	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
861	}
