873	/**
874	 * Send a pre-built JSON control frame to a client.
875	 *
876	 * Unlike ws_server_send() this does not wrap the payload in a chat response
877	 * envelope, which is what control and status frames need.
878	 */
879	int ws_server_send_json(const char* chat_id, const char* json)
880	{
881	    if (s_listen_fd < 0 || !s_running || json == NULL)
882	        return ERROR;
883	
884	    ws_client_t* client = lock_client_for_send(chat_id);
885	    int rc = -1;
886	    if (client) {
887	        rc = ws_send_frame(client, json, strlen(json));
888	        unlock_client(client);
889	    }
890	
891	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
892	}
