894	/**
895	 * Send a control frame to every connected client.
896	 *
897	 * For events that originate on the device and belong to whichever host
898	 * happens to be attached, rather than to one named peer: the UI's
899	 * push-to-talk button is the case this exists for, and the button has no
900	 * way to know which chat_id the host registered under -- it may not even
901	 * be connected yet when the screen is built.
902	 */
903	int ws_server_broadcast_json(const char* json)
904	{
905	    int sent = 0;
906	
907	    if (s_listen_fd < 0 || !s_running || json == NULL)
908	        return ERROR;
909	
910	    /* One client at a time, each claimed under the table lock and released
911	     * before moving on: a peer that is not reading must not hold up the
912	     * broadcast to the others, which is the whole reason sends no longer
913	     * share one mutex. */
914	    for (int i = 0; i < AGENT_WS_MAX_CLIENTS; i++) {
915	        int fd;
916	
917	        pthread_mutex_lock(&s_clients_mtx);
918	        if (!s_clients[i].active) {
919	            pthread_mutex_unlock(&s_clients_mtx);
920	            continue;
921	        }
922	        pthread_mutex_lock(&s_clients[i].tx_mtx);
923	        fd = s_clients[i].fd;
924	        pthread_mutex_unlock(&s_clients_mtx);
925	
926	        if (fd >= 0 && ws_send_frame(&s_clients[i], json, strlen(json)) == 0)
927	            sent++;
928	
929	        pthread_mutex_unlock(&s_clients[i].tx_mtx);
930	    }
931	
932	    syslog(LOG_INFO, "[%s] broadcast %s to %d client(s)\n", TAG, json, sent);
933	    return sent > 0 ? OK : ERROR;
934	}
935	
936	/**
937	 * Push one binary frame to a client.
938	 *
939	 * Used for raw stream payloads (currently microphone PCM) that would be
940	 * wasteful and fragile to carry as base64 inside JSON. Frames larger than
941	 * 65535 bytes are rejected by the encoder, so callers must chunk.
942	 */
943	int ws_server_send_binary(const char* chat_id, const void* data, size_t len)
944	{
945	    if (s_listen_fd < 0 || !s_running || data == NULL || len == 0)
946	        return ERROR;
947	
948	    ws_client_t* client = lock_client_for_send(chat_id);
949	    int rc = -1;
950	    if (client) {
951	        rc = ws_send_frame_op(client, data, len, WS_OPCODE_BINARY);
952	        unlock_client(client);
953	    }
954	
955	    return (client == NULL) ? ERROR : (rc == 0 ? OK : ERROR);
956	}
