958	int ws_server_stop(void)
959	{
960	    s_running = false;
961	    if (s_listen_fd >= 0) {
962	        close(s_listen_fd);
963	        s_listen_fd = -1;
964	    }
965	    syslog(LOG_INFO, "[%s] WebSocket server stopped\n", TAG);
966	    return OK;
967	}
