170	/* -- Persistence ------------------------------------------------- */
171	
172	static int cron_load_jobs(void)
173	{
174	    FILE* f = fopen(AGENT_CRON_FILE, "r");
175	
176	    if (!f) {
177	        syslog(LOG_INFO, "[%s] No cron file, starting fresh\n", TAG);
178	        s_job_count = 0;
179	        return OK;
180	    }
181	
182	    fseek(f, 0, SEEK_END);
183	    long fsize = ftell(f);
184	    fseek(f, 0, SEEK_SET);
185	
186	    if (fsize <= 0 || fsize > AGENT_CRON_FILE_MAX_SIZE) {
187	        syslog(LOG_WARNING, "[%s] Cron file invalid size: %ld\n", TAG, fsize);
188	        fclose(f);
189	        s_job_count = 0;
190	        return OK;
191	    }
192	
193	    char* buf = malloc(fsize + 1);
194	
195	    if (!buf) {
196	        fclose(f);
197	        return ERROR;
198	    }
199	
200	    size_t n = fread(buf, 1, fsize, f);
201	    buf[n] = '\0';
202	    fclose(f);
203	
204	    cJSON* root = cJSON_Parse(buf);
205	    free(buf);
206	
207	    if (!root) {
208	        syslog(LOG_WARNING, "[%s] Failed to parse cron JSON\n", TAG);
209	        s_job_count = 0;
210	        return OK;
211	    }
212	
213	    cJSON* jobs_arr = cJSON_GetObjectItem(root, "jobs");
214	
215	    if (!jobs_arr || !cJSON_IsArray(jobs_arr)) {
216	        cJSON_Delete(root);
217	        s_job_count = 0;
218	        return OK;
219	    }
220	
221	    s_job_count = 0;
222	    bool repaired = false;
223	    cJSON* item;
224	
225	    cJSON_ArrayForEach(item, jobs_arr)
226	    {
227	        if (s_job_count >= MAX_CRON_JOBS) {
228	            break;
229	        }
230	
231	        cron_job_t* job = &s_jobs[s_job_count];
232	
233	        if (cron_parse_job_item(item, job) != OK) {
234	            continue;
235	        }
236	
237	        if (cron_sanitize_destination(job)) {
238	            repaired = true;
239	        }
240	
241	        s_job_count++;
242	    }
243	
244	    cJSON_Delete(root);
245	    if (repaired) {
246	        cron_save_jobs();
247	    }
248	
249	    syslog(LOG_INFO, "[%s] Loaded %d cron jobs\n", TAG, s_job_count);
250	    return OK;
251	}
252	
253	static int cron_save_jobs(void)
254	{
255	    cJSON* root = cJSON_CreateObject();
256	    cJSON* jobs_arr = cJSON_CreateArray();
257	
258	    for (int i = 0; i < s_job_count; i++) {
259	        cron_job_t* job = &s_jobs[i];
260	        cJSON* item = cJSON_CreateObject();
261	
262	        cJSON_AddStringToObject(item, "id", job->id);
263	        cJSON_AddStringToObject(item, "name", job->name);
264	        cJSON_AddBoolToObject(item, "enabled", job->enabled);
265	        cJSON_AddStringToObject(item, "kind",
266	            job->kind == CRON_KIND_EVERY ? "every" : "at");
267	
268	        if (job->kind == CRON_KIND_EVERY) {
269	            cJSON_AddNumberToObject(item, "interval_s", job->interval_s);
270	        } else {
271	            cJSON_AddNumberToObject(item, "at_epoch", (double)job->at_epoch);
272	        }
273	
274	        cJSON_AddStringToObject(item, "message", job->message);
275	        cJSON_AddStringToObject(item, "channel", job->channel);
276	        cJSON_AddStringToObject(item, "chat_id", job->chat_id);
277	        cJSON_AddNumberToObject(item, "last_run", (double)job->last_run);
278	        cJSON_AddNumberToObject(item, "next_run", (double)job->next_run);
279	        cJSON_AddBoolToObject(item, "delete_after_run", job->delete_after_run);
280	
281	        if (job->action[0] != '\0') {
282	            cJSON_AddStringToObject(item, "action", job->action);
283	            cJSON_AddStringToObject(item, "action_args", job->action_args);
284	        }
285	
286	        if (job->wake_agent) {
287	            cJSON_AddBoolToObject(item, "wake_agent", true);
288	        }
289	
290	        cJSON_AddItemToArray(jobs_arr, item);
291	    }
292	
293	    cJSON_AddItemToObject(root, "jobs", jobs_arr);
294	
295	    char* json_str = cJSON_Print(root);
296	    cJSON_Delete(root);
297	
298	    if (!json_str) {
299	        syslog(LOG_ERR, "[%s] Failed to serialize cron jobs\n", TAG);
300	        return ERROR;
301	    }
302	
303	    FILE* f = fopen(AGENT_CRON_FILE, "w");
304	
305	    if (!f) {
306	        syslog(LOG_ERR, "[%s] Cannot open %s for write\n", TAG, AGENT_CRON_FILE);
307	        free(json_str);
308	        return ERROR;
309	    }
310	
311	    size_t len = strlen(json_str);
312	    size_t written = fwrite(json_str, 1, len, f);
313	    fclose(f);
314	    free(json_str);
315	
316	    if (written != len) {
317	        syslog(LOG_ERR, "[%s] Cron save incomplete: %d/%d bytes\n", TAG,
318	            (int)written, (int)len);
319	        return ERROR;
320	    }
321	
322	    syslog(LOG_INFO, "[%s] Saved %d cron jobs\n", TAG, s_job_count);
323	    return OK;
324	}
