326	/* -- Due-job processing ------------------------------------------ */
327	
328	static void cron_fire_job(cron_job_t* job, time_t now)
329	{
330	    syslog(LOG_INFO, "[%s] Cron job firing: %s (%s)\n", TAG, job->name, job->id);
331	
332	    if (job->wake_agent) {
333	        /* Proactive agent turn: the message is a prompt for the agent loop,
334	         * not a canned notification. The agent decides what to do (it may
335	         * call tools and consult skills), and its reply is delivered to
336	         * channel/chat_id by the normal outbound path. */
337	        agent_msg_t msg;
338	        memset(&msg, 0, sizeof(msg));
339	        strncpy(msg.channel, job->channel, sizeof(msg.channel) - 1);
340	        strncpy(msg.chat_id, job->chat_id, sizeof(msg.chat_id) - 1);
341	        msg.content = strdup(job->message);
342	        msg.internal = 1;  /* a prompt we wrote to ourselves, not user input */
343	
344	        if (msg.content) {
345	            syslog(LOG_INFO, "[%s] Waking agent: channel=%s chat_id=%s\n",
346	                TAG, msg.channel, msg.chat_id);
347	            if (message_bus_push_inbound(&msg) != OK) {
348	                syslog(LOG_WARNING, "[%s] Failed to wake agent\n", TAG);
349	                free(msg.content);
350	            }
351	        } else {
352	            syslog(LOG_WARNING, "[%s] OOM waking agent\n", TAG);
353	        }
354	
355	        job->last_run = now;
356	        return;
357	    }
358	
359	    if (job->action[0] != '\0') {
360	        /* Direct tool execution — no queue contention with agent loop */
361	        char tool_output[512];
362	        tool_output[0] = '\0';
363	
364	        syslog(LOG_INFO, "[%s] Executing action: %s args=%.128s\n",
365	            TAG, job->action, job->action_args);
366	
367	        int err = tool_registry_execute(job->action, job->action_args,
368	            tool_output, sizeof(tool_output));
369	
370	        if (err != OK) {
371	            syslog(LOG_WARNING, "[%s] Action %s failed: %s\n",
372	                TAG, job->action, tool_output);
373	        } else {
374	            syslog(LOG_INFO, "[%s] Action %s OK: %.128s\n",
375	                TAG, job->action, tool_output);
376	        }
377	
378	        /* Send a notification to the user about what happened.
379	         * Skip voice notification when the action itself failed —
380	         * speaking the failure message through voice channel can
381	         * trigger another round of audio close cascade errors. */
382	        if (err != OK
383	            && strcmp(job->channel, AGENT_CHAN_VOICE) == 0) {
384	            syslog(LOG_WARNING,
385	                "[%s] Skipping voice notification for failed action %s\n",
386	                TAG, job->action);
387	        } else if (job->channel[0] != '\0') {
388	            agent_msg_t notify;
389	            memset(&notify, 0, sizeof(notify));
390	            strncpy(notify.channel, job->channel, sizeof(notify.channel) - 1);
391	            strncpy(notify.chat_id, job->chat_id, sizeof(notify.chat_id) - 1);
392	            notify.content = strdup(job->message);
393	            if (notify.content) {
394	                if (message_bus_push_outbound(&notify) != OK) {
395	                    free(notify.content);
396	                }
397	            }
398	        }
399	    } else {
400	        /* Plain reminder — push directly to outbound */
401	        agent_msg_t msg;
402	        memset(&msg, 0, sizeof(msg));
403	        strncpy(msg.channel, job->channel, sizeof(msg.channel) - 1);
404	        strncpy(msg.chat_id, job->chat_id, sizeof(msg.chat_id) - 1);
405	        msg.content = strdup(job->message);
406	
407	        if (msg.content) {
408	            int err = message_bus_push_outbound(&msg);
409	            if (err != OK) {
410	                syslog(LOG_WARNING, "[%s] Failed to push cron message\n", TAG);
411	                free(msg.content);
412	            }
413	        }
414	    }
415	
416	    job->last_run = now;
417	}
