419	static void cron_process_due_jobs(void)
420	{
421	    time_t now = time(NULL);
422	    bool changed = false;
423	
424	    pthread_mutex_lock(&s_cron_lock);
425	
426	    for (int i = 0; i < s_job_count; i++) {
427	        cron_job_t* job = &s_jobs[i];
428	
429	        syslog(LOG_DEBUG,
430	            "[%s] Check job[%d] '%s': enabled=%d next_run=%lld now=%lld\n", TAG,
431	            i, job->name, job->enabled, (long long)job->next_run,
432	            (long long)now);
433	
434	        if (!job->enabled || job->next_run <= 0 || job->next_run > now) {
435	            continue;
436	        }
437	
438	        cron_fire_job(job, now);
439	
440	        if (job->kind == CRON_KIND_AT) {
441	            if (job->delete_after_run) {
442	                syslog(LOG_INFO, "[%s] Deleting one-shot: %s\n", TAG, job->name);
443	                for (int j = i; j < s_job_count - 1; j++) {
444	                    s_jobs[j] = s_jobs[j + 1];
445	                }
446	                s_job_count--;
447	                i--;
448	            } else {
449	                job->enabled = false;
450	                job->next_run = 0;
451	            }
452	        } else {
453	            job->next_run = now + job->interval_s;
454	        }
455	
456	        changed = true;
457	    }
458	
459	    if (changed) {
460	        cron_save_jobs();
461	    }
462	
463	    pthread_mutex_unlock(&s_cron_lock);
464	}
465	
466	static void* cron_task_main(void* arg)
467	{
468	    (void)arg;
469	
470	    while (s_cron_running) {
471	        /* Use timedwait instead of usleep so that cron_nudge() can
472	         * wake us immediately when a new job is added.  This also
473	         * survives NuttX deep-sleep better than plain usleep. */
474	        struct timespec ts;
475	        clock_gettime(CLOCK_REALTIME, &ts);
476	        ts.tv_sec += AGENT_CRON_CHECK_INTERVAL_MS / 1000;
477	
478	        pthread_mutex_lock(&s_cron_lock);
479	        pthread_cond_timedwait(&s_cron_wake, &s_cron_lock, &ts);
480	        pthread_mutex_unlock(&s_cron_lock);
481	
482	        cron_process_due_jobs();
483	    }
484	
485	    return NULL;
486	}
487	
488	static void compute_initial_next_run(cron_job_t* job)
489	{
490	    time_t now = time(NULL);
491	
492	    if (job->kind == CRON_KIND_EVERY) {
493	        job->next_run = now + job->interval_s;
494	    } else if (job->kind == CRON_KIND_AT) {
495	        if (job->at_epoch > now) {
496	            job->next_run = job->at_epoch;
497	        } else {
498	            job->next_run = 0;
499	            job->enabled = false;
500	        }
501	    }
502	}
