504	/* -- Public Functions -------------------------------------------- */
505	
506	int cron_service_init(void) { return cron_load_jobs(); }
507	
508	int cron_service_start(void)
509	{
510	    pthread_mutex_lock(&s_cron_lock);
511	
512	    if (s_cron_running) {
513	        pthread_mutex_unlock(&s_cron_lock);
514	        syslog(LOG_WARNING, "[%s] Cron task already running\n", TAG);
515	        return OK;
516	    }
517	
518	    time_t now = time(NULL);
519	    bool changed = false;
520	
521	    for (int i = 0; i < s_job_count; i++) {
522	        cron_job_t* job = &s_jobs[i];
523	
524	        if (!job->enabled) {
525	            continue;
526	        }
527	
528	        /* Stale job: next_run already set but in the past.
529	         * interval_s is relative to the previous action completion
530	         * (e.g. music playback end), so rescheduling to now+interval
531	         * would produce wrong timing.  Disable instead. */
532	        if (job->next_run > 0 && job->next_run <= now) {
533	            syslog(LOG_WARNING,
534	                "[%s] disabling stale job: %s (next_run %lld <= now %lld)\n",
535	                TAG, job->name, (long long)job->next_run, (long long)now);
536	            job->enabled = false;
537	            job->next_run = 0;
538	            changed = true;
539	            continue;
540	        }
541	
542	        if (job->next_run <= 0) {
543	            if (job->kind == CRON_KIND_EVERY) {
544	                job->next_run = now + job->interval_s;
545	            } else if (job->kind == CRON_KIND_AT && job->at_epoch > now) {
546	                job->next_run = job->at_epoch;
547	            }
548	        }
549	    }
550	
551	    if (changed) {
552	        cron_save_jobs();
553	    }
554	
555	    s_cron_running = true;
556	    pthread_mutex_unlock(&s_cron_lock);
557	
558	    int err = agent_task_create(cron_task_main, "cron", AGENT_CRON_STACK,
559	        NULL, AGENT_CRON_PRIO);
560	
561	    if (err != OK) {
562	        s_cron_running = false;
563	        syslog(LOG_ERR, "[%s] Failed to create cron task\n", TAG);
564	        return ERROR;
565	    }
566	
567	    syslog(LOG_INFO, "[%s] Cron started (%d jobs, interval %ds)\n", TAG,
568	        s_job_count, AGENT_CRON_CHECK_INTERVAL_MS / 1000);
569	    return OK;
570	}
571	
572	void cron_service_stop(void)
573	{
574	    if (s_cron_running) {
575	        s_cron_running = false;
576	        syslog(LOG_INFO, "[%s] Cron service stopping\n", TAG);
577	    }
578	}
579	
580	int cron_add_job(cron_job_t* job)
581	{
582	    pthread_mutex_lock(&s_cron_lock);
583	
584	    if (s_job_count >= MAX_CRON_JOBS) {
585	        syslog(LOG_WARNING, "[%s] Max cron jobs reached (%d)\n", TAG,
586	            MAX_CRON_JOBS);
587	        pthread_mutex_unlock(&s_cron_lock);
588	        return ERROR;
589	    }
590	
591	    cron_generate_id(job->id);
592	    cron_sanitize_destination(job);
593	
594	    job->enabled = true;
595	    job->last_run = 0;
596	    compute_initial_next_run(job);
597	
598	    s_jobs[s_job_count] = *job;
599	    s_job_count++;
600	
601	    cron_save_jobs();
602	
603	    /* Wake the cron thread so it re-evaluates with the new job */
604	    pthread_cond_signal(&s_cron_wake);
605	
606	    pthread_mutex_unlock(&s_cron_lock);
607	
608	    syslog(LOG_INFO,
609	        "[%s] Added job: %s (%s) kind=%s "
610	        "next=%lld ch=%s:%s\n",
611	        TAG, job->name, job->id, job->kind == CRON_KIND_EVERY ? "every" : "at",
612	        (long long)job->next_run, job->channel, job->chat_id);
613	    return OK;
614	}
615	
616	int cron_remove_job(const char* job_id)
617	{
618	    pthread_mutex_lock(&s_cron_lock);
619	
620	    for (int i = 0; i < s_job_count; i++) {
621	        if (strcmp(s_jobs[i].id, job_id) == 0) {
622	            syslog(LOG_INFO, "[%s] Removing job: %s (%s)\n", TAG, s_jobs[i].name,
623	                job_id);
624	
625	            for (int j = i; j < s_job_count - 1; j++) {
626	                s_jobs[j] = s_jobs[j + 1];
627	            }
628	            s_job_count--;
629	
630	            cron_save_jobs();
631	            pthread_mutex_unlock(&s_cron_lock);
632	            return OK;
633	        }
634	    }
635	
636	    pthread_mutex_unlock(&s_cron_lock);
637	    syslog(LOG_WARNING, "[%s] Cron job not found: %s\n", TAG, job_id);
638	    return ERROR;
639	}
640	
641	int cron_list_jobs(cron_job_t* out, int max_count)
642	{
643	    int count;
644	
645	    pthread_mutex_lock(&s_cron_lock);
646	    count = s_job_count < max_count ? s_job_count : max_count;
647	    memcpy(out, s_jobs, count * sizeof(cron_job_t));
648	    pthread_mutex_unlock(&s_cron_lock);
649	
650	    return count;
651	}
