int tool_get_health_execute(const char *input_json, char *output,
    size_t output_size)
{
    health_snapshot_t h;
    int n;

    (void)input_json;

    if (output == NULL || output_size == 0) {
        return ERROR;
    }

    health_monitor_get(&h);

