        "\"mic\":\"%s\",\"cron_jobs\":%u,\"issues\":%u,"
        "\"boot_count\":%u,\"reset_reason\":\"%s\",\"persist_ok\":%s}",
        health_monitor_state_name(h.state),
        h.stale ? "true" : "false",
        (unsigned long)h.uptime_s,
