/* ── Status sampling (background thread) ────────────────────── */

typedef struct {
    int count;
    int min_prio;
} task_count_ctx_t;

static void task_count_cb(FAR struct tcb_s* tcb, FAR void* arg)
{
    task_count_ctx_t* ctx = (task_count_ctx_t*)arg;

    if (!tcb || !ctx) {
        return;
    }
    ctx->count++;
    if (tcb->sched_priority < ctx->min_prio) {
        ctx->min_prio = tcb->sched_priority;
    }
}

